with enrichment(grammar_id,formation_value,usage_value,nuance_value,examples_value) as (
  values
    ('730e64d5-172e-49a3-8307-430e6926b374'::uuid,ARRAY['Sinformal であろう']::text[],ARRAY['Use this construction to express An auxiliary which indicates the writer''s conjecture which is not based on any particular information or evidence.. An auxiliary which indicates the writer''s conjecture which is not based on any particular information or evidence.']::text[],ARRAY['【Related Expression: だろう; まい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本経済は今後も成長を続けるであろう。","japanese_furigana":"日本経済は今後も成長を続けるであろう。","english":"The Japanese economy will probably still keep growing (literally: from now on, too)."},{"japanese":"このようなブームはもう二度と起こらないであろう。","japanese_furigana":"このようなブームはもう二度と起こらないであろう。","english":"Such a boom will probably not happen again."}]'::jsonb),
    ('29a0ce75-d5ab-4811-b75a-c0cf2b6c84d6'::uuid,ARRAY['(i) Verb てはいられない']::text[],ARRAY['Use this construction to express A phrase that is used when someone cannot be doing something or be in some state due to a given situation.. A phrase that is used when someone cannot be doing something or be in some state due to a given situation.']::text[],ARRAY['【Related Expression: ずにはいられない; わけにはいかない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"将来のことを考えると、いつまでもこんな仕事をしてはいられない。","japanese_furigana":"将来のことを考えると、いつまでもこんな仕事をしてはいられない。","english":"When I think about the future, (I realise) I can''t keep doing this kind of work forever."},{"japanese":"彼女があまりにも自分勝手だったので、一言言わないではいられなかった。","japanese_furigana":"彼女があまりにも自分勝手だったので、一言言わないではいられなかった。","english":"Because she was acting so selﬁshly, I couldn''t resist saying something to her."}]'::jsonb),
    ('1650b48a-7aab-4240-9c28-b643cadd0c39'::uuid,ARRAY['(i) Vて ばかりはいられない']::text[],ARRAY['Use this construction to express A phrase representing the idea that someone cannot just keep doing something or waste time being consumed by some emotion.. A phrase representing the idea that someone cannot just keep doing something or waste time being consumed by some emotion.']::text[],ARRAY['The core sense is A phrase representing the idea that someone cannot just keep doing something or waste time being consumed by some emotion.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"過去の業績に安住してばかりはいられない。","japanese_furigana":"過去の業績に安住してばかりはいられない。","english":"We just cannot be content with our past performance."},{"japanese":"確かにこれは深刻な事態だが、議論ばかりしてはいられない。","japanese_furigana":"確かにこれは深刻な事態だが、議論ばかりしてはいられない。","english":"Indeed, this is a serious situation, but we cannot just keep discussing it."}]'::jsonb),
    ('66d29a5c-ec8e-42ed-b5a6-d3c057a37191'::uuid,ARRAY['V1 ても V2 ても Where V1=V2']::text[],ARRAY['Use this construction to express A structure meaning “even if someone does something repeatedly”.. A structure meaning “even if someone does something repeatedly”.']::text[],ARRAY['【Related Expression: いくら~ても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"考えても考えても思い出せない。","japanese_furigana":"考えても考えても思い出せない。","english":"No matter how much/hard I try (literally: think), I cannot remember it."},{"japanese":"働いても働いてもお金が貯まらない。","japanese_furigana":"働いても働いてもお金が貯まらない。","english":"No matter how much/hard I work, I cannot save money."}]'::jsonb),
    ('39f22b9c-73d9-4c3e-a1b9-f4c3d1c734be'::uuid,ARRAY['(i) Noun { でも / じゃ } あるまいし']::text[],ARRAY['Use this construction to express A phrase expressing the speaker’s belief that someone’s action is based on mistaken identity of himself/herself and also expressing the speaker’s critical comments about someone’s behaviour.. A phrase expressing the speaker’s belief that someone’s action is based on mistaken identity of himself/herself and also expressing the speaker’s critical comments about someone’s behaviour.']::text[],ARRAY['The core sense is A phrase expressing the speaker’s belief that someone’s action is based on mistaken identity of himself/herself and also expressing the speaker’s critical comments about someone’s behaviour.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"幼稚園児｛でも/じゃ｝あるまいし一人で学校に行きなさい。","japanese_furigana":"幼稚園児｛でも/じゃ｝あるまいし一人で学校に行きなさい。","english":"You are not a kindergarten pupil. Go to school by yourself."},{"japanese":"フランスに行けるわけ｛でも/じゃ｝あるまいし、どうしてそんなにフランス語を勉強しているの。","japanese_furigana":"フランスに行けるわけ｛でも/じゃ｝あるまいし、どうしてそんなにフランス語を勉強しているの。","english":"There''s no way you can get to France. How come you''re studying French so hard?"}]'::jsonb),
    ('4cf653c2-cfb1-4a07-89aa-d1e1f34661f3'::uuid,ARRAY['Noun (particle) でも, (Noun (particle) でも,) でも 、Wh-word (particle) でも']::text[],ARRAY['Use this construction to express A structure indicating that what is expressed in the main/subordinate clause is applicable to anyone, anything, any place or any time.. A structure indicating that what is expressed in the main/subordinate clause is applicable to anyone, anything, any place or any time.']::text[],ARRAY['The core sense is A structure indicating that what is expressed in the main/subordinate clause is applicable to anyone, anything, any place or any time.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"そんなことは子供でも誰でも知っているよ。","japanese_furigana":"そんなことは子供でも誰でも知っているよ。","english":"That sort of thing is known even to a child or to anybody."},{"japanese":"私って漫画でも何でも読み出すと止まらないタイプなの。","japanese_furigana":"私って漫画でも何でも読み出すと止まらないタイプなの。","english":"I''m the type of person who cannot stop reading manga or whatever once I start."}]'::jsonb),
    ('a225fc5e-889f-434e-939a-67ada1738569'::uuid,ARRAY['Vて やる']::text[],ARRAY['Use this construction to express An auxiliary verb which expresses the idea that someone does something undesirable to someone else when he/she knows his/her action will cause hardship or trouble.. An auxiliary verb which expresses the idea that someone does something undesirable to someone else when he/she knows his/her action will cause hardship or trouble.']::text[],ARRAY['【Related Expression: くれる; もらう】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は正をからかってやった。","japanese_furigana":"私は正をからかってやった。","english":"I teased Tadashi."},{"japanese":"ルームメートが部屋を全然掃除しないので、文句を言ってやった。","japanese_furigana":"ルームメートが部屋を全然掃除しないので、文句を言ってやった。","english":"Because my roommate never cleans our room, I complained (to her about it)."}]'::jsonb),
    ('a6cb88eb-b316-4316-a624-555db06ad46e'::uuid,ARRAY['(i) Verb て仕方がない']::text[],ARRAY['Use this construction to express A phrase that represents emotions the speaker/writer cannot control or sensations/situations he/she cannot bear.. A phrase that represents emotions the speaker/writer cannot control or sensations/situations he/she cannot bear.']::text[],ARRAY['【Related Expression: てならない; て堪らない; (とい)ったらない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"会社の理不尽なリストラに腹が立って仕方がない。","japanese_furigana":"会社の理不尽なリストラに腹が立って仕方がない。","english":"I''m so mad at the company''s unreasonable restructuring (i.e., laying off workers) (and cannot control my anger)."},{"japanese":"久しぶりに妻や子供たちに会えるので嬉しくて仕方がない。","japanese_furigana":"久しぶりに妻や子供たちに会えるので嬉しくて仕方がない。","english":"Because I get to see my wife and children for the ﬁrst time in a long while, I am so happy (and can hardly control my emotion)."}]'::jsonb),
    ('4c94a2ea-8303-42ff-b38e-81607fcfee69'::uuid,ARRAY['Vて 初めて']::text[],ARRAY['Use this construction to express A phrase which expresses the idea that someone does something or something happens only after something else happens or something else is done.. A phrase which expresses the idea that someone does something or something happens only after something else happens or something else is done.']::text[],ARRAY['The core sense is A phrase which expresses the idea that someone does something or something happens only after something else happens or something else is done.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"アメリカへ来て初めて竜巻を見た。","japanese_furigana":"アメリカへ来て初めて竜巻を見た。","english":"It was not until I came to America that I saw a tornado."},{"japanese":"日本で生活して初めて日本人のものの考え方が分かってきた。","japanese_furigana":"日本で生活して初めて日本人のものの考え方が分かってきた。","english":"It was not until I lived in Japan that I started to understand how Japanese people think."}]'::jsonb),
    ('694af1db-40e5-40fa-83d6-f7f480de1b37'::uuid,ARRAY['Canonical pattern: 〜と（並列）']::text[],ARRAY['Use this construction to express A particle which lists things exhaustively.. A particle which lists things exhaustively.']::text[],ARRAY['【Related Expression: に (and); と2; や】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"マイクとディック（と）は学生だ・です。","japanese_furigana":"マイクとディック（と）は学生だ・です。","english":"Mike and Dick are students."},{"japanese":"私は英語と日本語を話す。","japanese_furigana":"私は英語と日本語を話す。","english":"I speak English and Japanese."}]'::jsonb),
    ('cb97461f-85c5-408c-b1b9-4795e213f07b'::uuid,ARRAY['Canonical pattern: 〜と（相手）']::text[],ARRAY['Use this construction to express A particle marking the noun phrase which maintains a reciprocal relationship with the subject of a clause.. A particle marking the noun phrase which maintains a reciprocal relationship with the subject of a clause.']::text[],ARRAY['【Related Expression: に4; と1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はアンディーと一緒にパーティーに行った・行きました。","japanese_furigana":"私はアンディーと一緒にパーティーに行った・行きました。","english":"I went to a party (together) with Andy."},{"japanese":"トムはジョンとよくテニスをする。","japanese_furigana":"トムはジョンとよくテニスをする。","english":"Tom often plays tennis with John."}]'::jsonb),
    ('4df7519d-e2f8-47a7-82fe-9bcfe7801787'::uuid,ARRAY['(i) NP とあって']::text[],ARRAY['Use this construction to express A phrase that introduces a reason when the speaker/writer considers it natural that someone does something or is in some state, or that something takes place for that reason.. A phrase that introduces a reason when the speaker/writer considers it natural that someone does something or is in some state, or that something takes place for that reason.']::text[],ARRAY['【Related Expression: ので; から】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ボーナス後の連休とあって、観光地はどこも人でいっぱいだ。","japanese_furigana":"ボーナス後の連休とあって、観光地はどこも人でいっぱいだ。","english":"Because this is the series of holidays after the bonus season, (not surprisingly) all the tourist spots are crowded."},{"japanese":"夏休みが始まったとあって、子供たちはみんな嬉しそうだ。","japanese_furigana":"夏休みが始まったとあって、子供たちはみんな嬉しそうだ。","english":"Summer vacation has begun, so the children all look happy."}]'::jsonb),
    ('c740cefa-af3d-422e-ba0c-26e0f1a6d0b0'::uuid,ARRAY['Noun 1 といい Noun 2 といい']::text[],ARRAY['Use this construction to express A structure that introduces multiple perspectives when describing a person or a thing.. A structure that introduces multiple perspectives when describing a person or a thing.']::text[],ARRAY['【Related Expression: も~も】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このコーヒーは味といい香りといい、申し分ありません。","japanese_furigana":"このコーヒーは味といい香りといい、申し分ありません。","english":"This coffee is perfect in terms of both ﬂavour and aroma."},{"japanese":"内容といい話し方といい、見事なスピーチでした。","japanese_furigana":"内容といい話し方といい、見事なスピーチでした。","english":"It was a splendid speech in terms of content as well as delivery."}]'::jsonb),
    ('e2ea22d7-f58c-407d-87f5-fada53acb3eb'::uuid,ARRAY['Canonical pattern: 〜という']::text[],ARRAY['Use this construction to express A phrase marking information which identifies or explains the noun following the phrase.. A phrase marking information which identifies or explains the noun following the phrase.']::text[],ARRAY['The core sense is A phrase marking information which identifies or explains the noun following the phrase.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"「雪国」という小説を読んだ・読みました。","japanese_furigana":"「雪国」という小説を読んだ・読みました。","english":"I read a novel called Snow Country."},{"japanese":"山田さんが入院したという知らせを聞いた・聞きました。","japanese_furigana":"山田さんが入院したという知らせを聞いた・聞きました。","english":"I heard the news that Mr. Yamada has been hospitalised."}]'::jsonb),
    ('a7433de0-11cf-4ca1-8572-9f24c7154a2d'::uuid,ARRAY['Sinformal ということは']::text[],ARRAY['Use this construction to express A phrase which changes a sentence into a topic noun clause.. A phrase which changes a sentence into a topic noun clause.']::text[],ARRAY['【Related Expression: こと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼がこの集まりに来ないということは考えられない。","japanese_furigana":"彼がこの集まりに来ないということは考えられない。","english":"It is unthinkable that he won''t come to this meeting."},{"japanese":"手紙が戻って来たということは彼女はもうこの住所にはいないということだ。","japanese_furigana":"手紙が戻って来たということは彼女はもうこの住所にはいないということだ。","english":"The fact that the letter came back means that she no longer lives at this address."}]'::jsonb),
    ('41388aa9-f254-4682-8922-dc8542d3d8e7'::uuid,ARRAY['(i) Noun/Adjective な stem というのは']::text[],ARRAY['Use this construction to express A structure which is used in interpreting, explaining, or defining a word, a phrase, or a sentence.. A structure which is used in interpreting, explaining, or defining a word, a phrase, or a sentence.']::text[],ARRAY['【Related Expression: と言うことは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"パソコンというのはパーソナル・コンピュータのことだ。","japanese_furigana":"パソコンというのはパーソナル・コンピュータのことだ。","english":"Pasokon means personal computer."},{"japanese":"過労死というのは働き過ぎがもとで死ぬ（という）ことだ。","japanese_furigana":"過労死というのは働き過ぎがもとで死ぬ（という）ことだ。","english":"Karoushi means to die from overwork."}]'::jsonb),
    ('60e37d71-51d9-42c4-9576-a1318baf09c5'::uuid,ARRAY['(i) Adjective い informal というより ( は )、(むしろ)Adjective い/な']::text[],ARRAY['Use this construction to express A phrase that is used to indicate more accurate characterisation of someone or something.. A phrase that is used to indicate more accurate characterisation of someone or something.']::text[],ARRAY['The core sense is A phrase that is used to indicate more accurate characterisation of someone or something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"今年の夏は涼しいというよりは寒かった。","japanese_furigana":"今年の夏は涼しいというよりは寒かった。","english":"This summer was cold rather than cool."},{"japanese":"カーラは臆病というより（は）むしろ用心深い。","japanese_furigana":"カーラは臆病というより（は）むしろ用心深い。","english":"Kara is cautious rather than timid."}]'::jsonb),
    ('2fe027ca-d237-461d-b5e6-aab7b200255f'::uuid,ARRAY['(i) Sinformal という風に']::text[],ARRAY['Use this construction to express A phrase which expresses a manner or a way in which someone does something.. A phrase which expresses a manner or a way in which someone does something.']::text[],ARRAY['【Related Expression: と言うように】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼はどうしようもないという風に首を振った。","japanese_furigana":"彼はどうしようもないという風に首を振った。","english":"He shook his head as if to say that there was no way out."},{"japanese":"私は河村さんは来られないという風に聞いている。","japanese_furigana":"私は河村さんは来られないという風に聞いている。","english":"I have been informed that Mr. Kawamura cannot come. (literally: I have been informed in such a way that I understand that Mr. Kawamura cannot come.)"}]'::jsonb),
    ('4d10eb99-ec53-47e2-a33d-33002c4862a2'::uuid,ARRAY['(i) Noun 1 、Noun 2 (、…) といった Noun']::text[],ARRAY['Use this construction to express A compound particle that introduces examples.. A compound particle that introduces examples.']::text[],ARRAY['【Related Expression: と言う; と言うような; などの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ドイツ、フランス、ロシアといった国々が戦争に反対した。","japanese_furigana":"ドイツ、フランス、ロシアといった国々が戦争に反対した。","english":"Countries such as Germany, France and Russia opposed the war."},{"japanese":"このエンジンで一番困るのはパワーが弱い、製造コストが高いといった問題だ。","japanese_furigana":"このエンジンで一番困るのはパワーが弱い、製造コストが高いといった問題だ。","english":"The problems that are giving me the most trouble with this engine are things like weak power and high production costs."}]'::jsonb),
    ('b4344a6f-8fd1-4842-9c3d-43d64c6748d4'::uuid,ARRAY['(i) {V/Adjectiveい}informal といったところだ 。']::text[],ARRAY['Use this construction to express A phrase the speaker/writer uses to explain something in a brief/rough manner.. A phrase the speaker/writer uses to explain something in a brief/rough manner.']::text[],ARRAY['The core sense is A phrase the speaker/writer uses to explain something in a brief/rough manner.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"9月になって猛暑も一段落といったところです。","japanese_furigana":"9月になって猛暑も一段落といったところです。","english":"I''d say the searing heat levelled off in September."},{"japanese":"ここは山というよりは、小高い丘といったところだ。","japanese_furigana":"ここは山というよりは、小高い丘といったところだ。","english":"I''d say that this is more of a (small) hill than a mountain."}]'::jsonb),
    ('ed20a2b3-1b70-43b4-aff1-0a47c015d129'::uuid,ARRAY['(i) どうにも Vpotential negative ない']::text[],ARRAY['Use this construction to express A structure indicating that no matter how hard someone may try, something is impossible.. A structure indicating that no matter how hard someone may try, something is impossible.']::text[],ARRAY['【Related Expression: どうにもこうにも~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私には小説などはどうにも書けない。","japanese_furigana":"私には小説などはどうにも書けない。","english":"I’d never be able to write something like a novel, no matter how hard I try."},{"japanese":"この作文は間違いがひどくてどうにも直しようがない。","japanese_furigana":"この作文は間違いがひどくてどうにも直しようがない。","english":"This composition has such awful mistakes that there is no way to ﬁx it."}]'::jsonb),
    ('becf6c13-e5ca-46ef-b271-04488c10771a'::uuid,ARRAY['(i) {V/Adjectiveい}informal ところから']::text[],ARRAY['Use this construction to express A phrase that introduces the origins of names, theories, ideas and events.. A phrase that introduces the origins of names, theories, ideas and events.']::text[],ARRAY['【Related Expression: ことから; ので; から】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この宝石は猫の目に似ているところから「猫目石」と名づけられている。","japanese_furigana":"この宝石は猫の目に似ているところから「猫目石」と名づけられている。","english":"This gem is called \"cat''s-eye\" because it resembles a cat''s eye."},{"japanese":"私が両者にそのことを十分説明しなかったところから誤解が生じた。","japanese_furigana":"私が両者にそのことを十分説明しなかったところから誤解が生じた。","english":"The misunderstanding was caused by the fact that I didn''t explain it to both of them fully."}]'::jsonb),
    ('e7e434c4-928d-48c7-a79d-d64121c21019'::uuid,ARRAY['(i) Vinformal ところだ']::text[],ARRAY['Use this construction to express Someone/something is in the state where he/it is just about to do something, is doing something, has done something, or has been doing something.. Someone/something is in the state where he/it is just about to do something, is doing something, has done something, or has been doing something.']::text[],ARRAY['【Related Expression: ばかり; 時】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"春江は晩ご飯を食べるところだ・です。","japanese_furigana":"春江は晩ご飯を食べるところだ・です。","english":"Harue is just about to eat her supper."},{"japanese":"春江は晩ご飯を食べているところだ・です。","japanese_furigana":"春江は晩ご飯を食べているところだ・です。","english":"Harue is in the midst of eating her supper."}]'::jsonb),
    ('517a1512-7fa2-458c-9bd3-b7d95b4964ca'::uuid,ARRAY['(i) {V/Adjectiveい}informal nonpast どころではない']::text[],ARRAY['Use this construction to express A phrase indicating that an action/state is simply impossible due to an adverse situation.. A phrase indicating that an action/state is simply impossible due to an adverse situation.']::text[],ARRAY['【Related Expression: どころか; こどろのはなしではない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"自分のことで精一杯で、人のことなど考えるどころではない。","japanese_furigana":"自分のことで精一杯で、人のことなど考えるどころではない。","english":"I''m so busy with my own things that I simply can''t think of other people''s matters (right now)."},{"japanese":"年末なのに多忙で、海外旅行（をする）どころではなかった。","japanese_furigana":"年末なのに多忙で、海外旅行（をする）どころではなかった。","english":"I was so busy toward the end of the year that there was no way I could travel abroad."}]'::jsonb),
    ('09186c04-d80b-4edc-9d7d-9dad00b7a334'::uuid,ARRAY['Noun として']::text[],ARRAY['Use this construction to express A compound particle which indicates the capacity, role or function of someone or something.. A compound particle which indicates the capacity, role or function of someone or something.']::text[],ARRAY['The core sense is A compound particle which indicates the capacity, role or function of someone or something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"田中さんはセールスマンとして採用された・されました。","japanese_furigana":"田中さんはセールスマンとして採用された・されました。","english":"Mr. Tanaka was hired as a salesman."},{"japanese":"私は医者としてあなたに言います。","japanese_furigana":"私は医者としてあなたに言います。","english":"I''ll tell you (this) as a doctor."}]'::jsonb),
    ('20002886-16f1-4905-84e4-f40d5bd70e63'::uuid,ARRAY['Noun としては']::text[],ARRAY['Use this construction to express A compound particle which indicates a standard for comparisons.. A compound particle which indicates a standard for comparisons.']::text[],ARRAY['【Related Expression: にしては】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このステーキは日本のステーキとしては安い・安いです。","japanese_furigana":"このステーキは日本のステーキとしては安い・安いです。","english":"This steak is inexpensive for Japanese steak."},{"japanese":"ジョンソンさんは日本語の一年生としては日本語が上手だ。","japanese_furigana":"ジョンソンさんは日本語の一年生としては日本語が上手だ。","english":"Mr. Johnson is good at Japanese for a first-year student (of Japanese)."}]'::jsonb),
    ('e052ceed-11d7-4d35-95d3-35fed2f13abf'::uuid,ARRAY['(i) Noun 1 は Noun 2 (だ) とする']::text[],ARRAY['Use this construction to express A phrase indicating that someone assumes something.. A phrase indicating that someone assumes something.']::text[],ARRAY['【Related Expression: にする; となると】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"温度は一定（だ）とする。","japanese_furigana":"温度は一定（だ）とする。","english":"We assume that the temperature is constant."},{"japanese":"一日に五百マイル運転できるとすれば・すると、何日で着きますか。","japanese_furigana":"一日に五百マイル運転できるとすれば・すると、何日で着きますか。","english":"Assuming that we can drive 500 miles a day, how many days will it take to get there?"}]'::jsonb),
    ('c92c7d01-6324-4097-80a2-aed9f56b855f'::uuid,ARRAY['Sound Symbolism とする']::text[],ARRAY['Use this construction to express To have a sensory or psychological experience.. To have a sensory or psychological experience.']::text[],ARRAY['The core sense is To have a sensory or psychological experience.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"あの人はちょっとしたことでかっとする。","japanese_furigana":"あの人はちょっとしたことでかっとする。","english":"That person flares up at the slightest provocation."},{"japanese":"あの男の人は目がギョロリとしている。","japanese_furigana":"あの男の人は目がギョロリとしている。","english":"He has goggling eyes."}]'::jsonb),
    ('71e79adf-04da-4ffc-a5b3-8047c3a5ade8'::uuid,ARRAY['(i) どちらかと言うと (Xというよりは)Y。 Where X=Noun{∅/だ/だった}/Adjectiveいinformal/Adjectiveなstem{∅/だ/だった}; Y=Noun{だ/だった}/Adjectiveいinformal/Adjectiveな{だ/だった}']::text[],ARRAY['Use this construction to express A phrase indicating that the speaker/writer chooses one alternative over another in a tentative way.. A phrase indicating that the speaker/writer chooses one alternative over another in a tentative way.']::text[],ARRAY['【Related Expression: どちらかと言えば; むしろ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼はどちらかと言うと教育者というより（は）研究者だ。","japanese_furigana":"彼はどちらかと言うと教育者というより（は）研究者だ。","english":"He is more like a researcher than an educator."},{"japanese":"私はどちらかと言うと外向的というより（は）内向的だ。","japanese_furigana":"私はどちらかと言うと外向的というより（は）内向的だ。","english":"I''m more of an introvert than an extrovert."}]'::jsonb),
    ('28909ff4-ffbe-4365-93b4-4f02d11aaa25'::uuid,ARRAY['(i) とても Vnegative ない']::text[],ARRAY['Use this construction to express A structure that is used to deny emphatically the ability of someone/something or possibility of an event, state or action. A structure that is used to deny emphatically the ability of someone/something or possibility of an event, state or action']::text[],ARRAY['【Related Expression: とうてい~ない; 全く~ない; 決して~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この仕事はとても私にはできない。","japanese_furigana":"この仕事はとても私にはできない。","english":"I cannot possibly do this job."},{"japanese":"吉岡さんはとても私の勝てる相手ではない。","japanese_furigana":"吉岡さんはとても私の勝てる相手ではない。","english":"Mr. Yoshioka is someone I couldn''t possibly beat. (literally: Mr. Yoshioka is not someone I could possibly beat.)"}]'::jsonb),
    ('52b2c658-b753-4bd8-b4bd-ff45f3aa1208'::uuid,ARRAY['(i) Noun 1 とでも言うべき Noun 2']::text[],ARRAY['Use this construction to express A phrase that introduces a noun (or noun phrase) to describe the nature of someone or something.. A phrase that introduces a noun (or noun phrase) to describe the nature of someone or something.']::text[],ARRAY['【Related Expression: と言う; である; のような】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あれは運命とでも言うべき出来事だった。","japanese_furigana":"あれは運命とでも言うべき出来事だった。","english":"That was an incident that could be called fate."},{"japanese":"これはエッセイ的なサイトとでも言うべきでしょう。","japanese_furigana":"これはエッセイ的なサイトとでも言うべきでしょう。","english":"This should probably be described as an essay-like website."}]'::jsonb),
    ('882dd8cf-0f77-4882-b46e-7b79ccf21bbc'::uuid,ARRAY['Noun となる']::text[],ARRAY['Use this construction to express A phrase which expresses the idea that someone or something becomes something.. A phrase which expresses the idea that someone or something becomes something.']::text[],ARRAY['The core sense is A phrase which expresses the idea that someone or something becomes something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"吉田さんが初代の委員長となった。","japanese_furigana":"吉田さんが初代の委員長となった。","english":"Mr. Yoshida has become the first committee chairman."},{"japanese":"その土地は結局国の所有物となった。","japanese_furigana":"その土地は結局国の所有物となった。","english":"That land eventually become state property."}]'::jsonb),
    ('d4f16dce-a99e-4d61-8d0f-b2ef26c8e914'::uuid,ARRAY['(i) Noun となると']::text[],ARRAY['Use this construction to express A phrase which expresses the idea "when it comes to" or "if it is true that".. A phrase which expresses the idea "when it comes to" or "if it is true that".']::text[],ARRAY['【Related Expression: とすると】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は機械のこととなると何も分からない。","japanese_furigana":"私は機械のこととなると何も分からない。","english":"When it comes to mechanical things, I don''t understand anything."},{"japanese":"彼が手伝ってくれないとなると誰かほかの人を頼むしかない。","japanese_furigana":"彼が手伝ってくれないとなると誰かほかの人を頼むしかない。","english":"If it''s true that he is not going to help us, we''ll have no alternative but to ask someone else."}]'::jsonb),
    ('770d320d-8568-47fe-828e-7aab14b72052'::uuid,ARRAY['Sinformal との Noun だ after Adjectiveなstem and Noun is often omitted']::text[],ARRAY['Use this construction to express A phrase that presents the content of the referent of the following noun (e.g., a report, notice, news, view).. A phrase that presents the content of the referent of the following noun (e.g., a report, notice, news, view).']::text[],ARRAY['【Related Expression: という】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"経済情勢は悪化しているとの見方が優勢だ。","japanese_furigana":"経済情勢は悪化しているとの見方が優勢だ。","english":"The view that the economic situation is worsening is dominant."},{"japanese":"邦画の入場者数がハリウッド映画を上回って1位になったのは始めて(だ)とのことだ。","japanese_furigana":"邦画の入場者数がハリウッド映画を上回って1位になったのは始めて(だ)とのことだ。","english":"(It is said that) Apparently this is the first time that the size of the audience for a Japanese movie has exceeded that of a Hollywood movie, making it No. 1."}]'::jsonb),
    ('82a8f0ad-439f-4432-9141-346eff715e5e'::uuid,ARRAY['(i) {V/Adjectiveい}informal とは']::text[],ARRAY['Use this construction to express A compound particle marking an event, action or state that the speaker/writer does not expect and that causes him/her to feel some emotion. A compound particle marking an event, action or state that the speaker/writer does not expect and that causes him/her to feel some emotion']::text[],ARRAY['【Related Expression: と言うのは; ことに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼が自分のベンチャー会社を立ち上げるとは思いもしなかった。","japanese_furigana":"彼が自分のベンチャー会社を立ち上げるとは思いもしなかった。","english":"I never thought that he would launch his own venture business."},{"japanese":"あんないい店がなくなったとは残念だ。","japanese_furigana":"あんないい店がなくなったとは残念だ。","english":"It is too bad that such a nice shop is gone."}]'::jsonb),
    ('19f7d962-88fd-4792-942c-cb15abb9e073'::uuid,ARRAY['(i) Direct Quotation とばかりに']::text[],ARRAY['Use this construction to express A phrase that indicates that someone does something in order to convey something or in such a way that someone is convinced that something is the case.. A phrase that indicates that someone does something in order to convey something or in such a way that someone is convinced that something is the case.']::text[],ARRAY['【Related Expression: といわんばかりに; と言うよう/風に; と】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"悟は「黙ってついてこい」とばかりに先に立って歩き出した。","japanese_furigana":"悟は「黙ってついてこい」とばかりに先に立って歩き出した。","english":"Satoru started off (literally: began to walk ahead) as if to say: \"Don''t say anything and follow me.\""},{"japanese":"課長は余計な質問はするなとばかりに私をにらみつけた。","japanese_furigana":"課長は余計な質問はするなとばかりに私をにらみつけた。","english":"My section chief glared at me as if to tell me not to ask any unnecessary questions."}]'::jsonb),
    ('aada4f12-41e3-4679-9fd3-e9c697667592'::uuid,ARRAY['(i) Sinformal とは言え だ after Adjectiveなstem and Noun is omitted']::text[],ARRAY['Use this construction to express A conjunctive phrase meaning “although it is said that”. A conjunctive phrase meaning “although it is said that”']::text[],ARRAY['【Related Expression: と(は)いっても; とは言うものの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"夏とは言え、ここはまだちょっと肌寒いくらいの涼しさだ。","japanese_furigana":"夏とは言え、ここはまだちょっと肌寒いくらいの涼しさだ。","english":"Although it is summer, it is still cool here—almost to the extent that it can be called a little chilly."},{"japanese":"時間がなかったとは言え、ジェーンにこれくらいのレポートが書けないはずはない。","japanese_furigana":"時間がなかったとは言え、ジェーンにこれくらいのレポートが書けないはずはない。","english":"(i) Even admitting that Jane didn''t have much time, I don''t believe that she couldn''t write a (simple) report like this. (ii) Although Jane says that she didn''t have much time (or you say that Jane didn''t have much time), I don''t believe that she couldn''t write a (simple) report like this."}]'::jsonb),
    ('29741899-4e9a-483b-9184-7ddfc4a331ae'::uuid,ARRAY['Sinformal とは限らない']::text[],ARRAY['Use this construction to express A phrase which expresses the idea "not necessarily".. A phrase which expresses the idea "not necessarily".']::text[],ARRAY['The core sense is A phrase which expresses the idea "not necessarily".; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"体の弱い人が早く死ぬとは限らない。","japanese_furigana":"体の弱い人が早く死ぬとは限らない。","english":"Frail people do not necessarily die young."},{"japanese":"高い物がいつも・必ずしも安い物よりいいとは限らない。","japanese_furigana":"高い物がいつも・必ずしも安い物よりいいとは限らない。","english":"Expensive things are not always / necessarily better than inexpensive ones."}]'::jsonb),
    ('fa7c0152-e69a-4657-8490-f38b796d8c29'::uuid,ARRAY['ともすると Verb']::text[],ARRAY['Use this construction to express A phrase that expresses the idea that something is likely to take place.. A phrase that expresses the idea that something is likely to take place.']::text[],ARRAY['【Related Expression: ともすれば; ややもすると; ややもすれば; どうかすると】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"切れ味のよい議論はともすると言葉の暴力となる。","japanese_furigana":"切れ味のよい議論はともすると言葉の暴力となる。","english":"A sharp debate is apt to lead to a violent argument."},{"japanese":"親は自分の子供にはともすると点数が甘くなりがちだ。","japanese_furigana":"親は自分の子供にはともすると点数が甘くなりがちだ。","english":"Parents tend to be more permissive (literally: lenient in grading) when it comes to their own children."}]'::jsonb),
    ('0674ce2d-903d-4fe3-9d85-445b6c62f5ca'::uuid,ARRAY['(i) V1informal nonpast ともなく V2 Where V1=V2']::text[],ARRAY['Use this construction to express A phrase indicating that the subject does something without paying much attention, or that when, where, to whom, etc., something took place is unclear.. A phrase indicating that the subject does something without paying much attention, or that when, where, to whom, etc., something took place is unclear.']::text[],ARRAY['【Related Expression: ともなしに; となく】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"散歩をしているうちに、来るともなく駅まで来てしまった。","japanese_furigana":"散歩をしているうちに、来るともなく駅まで来てしまった。","english":"While I was taking a walk, I came as far as the station without intending to."},{"japanese":"我が家ではいつからともなく正月にスキーに行く習慣が始まった。","japanese_furigana":"我が家ではいつからともなく正月にスキーに行く習慣が始まった。","english":"We do not know when, but my family started a tradition of going skiing on New Year''s Day."}]'::jsonb),
    ('4962c626-2b14-4363-a09f-9e24700bb6e8'::uuid,ARRAY['(i) どんなに ～ ( こと ) か']::text[],ARRAY['Use this construction to express A structure that indicates an exclamation about the degree to which an action or state takes/took place.. A structure that indicates an exclamation about the degree to which an action or state takes/took place.']::text[],ARRAY['【Related Expression: どれほど~(こと)は; いかない~(こと)か】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"兄は病気が治ってどんなに嬉しかったことか。","japanese_furigana":"兄は病気が治ってどんなに嬉しかったことか。","english":"How glad my elder brother was when he recovered from his illness!"},{"japanese":"父は母をどんなに愛していたことか。","japanese_furigana":"父は母をどんなに愛していたことか。","english":"How dearly my father loved my mother!"}]'::jsonb),
    ('1aa1f1e8-eed7-4143-b392-78b9b2ff0bc2'::uuid,ARRAY['(i) Noun と共に']::text[],ARRAY['Use this construction to express A phrase which is used to express the idea that A and B share a common property or do the same thing together, that two things take place at the same time, or that someone or something possesses two properties.. A phrase which is used to express the idea that A and B share a common property or do the same thing together, that two things take place at the same time, or that someone or something possesses two properties.']::text[],ARRAY['【Related Expression: に従って; にともなって; につれて; と同時に; と一緒に; と並んで; と同じく】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"スタインベックはへミングウィイと共にアメリカの代表的作家の一人だ。","japanese_furigana":"スタインベックはへミングウィイと共にアメリカの代表的作家の一人だ。","english":"Steinbeck, as well as Hemingway, is a writer representative of American writers."},{"japanese":"私は職場の同僚達と共にそのデモに参加した。","japanese_furigana":"私は職場の同僚達と共にそのデモに参加した。","english":"I took part in the demonstration with my office colleagues."}]'::jsonb),
    ('2854b5b7-c89d-480e-867c-97b13697077e'::uuid,ARRAY['(i) Noun と同時に']::text[],ARRAY['Use this construction to express A phrase which is used to express the idea that someone does something or something takes place at the same time as another action or event, or that someone or something is in two states simultaneously.. A phrase which is used to express the idea that someone does something or something takes place at the same time as another action or event, or that someone or something is in two states simultaneously.']::text[],ARRAY['【Related Expression: と共に; 途端(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼は大学卒業と同時に銀行に就職した。","japanese_furigana":"彼は大学卒業と同時に銀行に就職した。","english":"He got a job at a bank at the time of (literally: at the same time as) his graduation from college."},{"japanese":"部屋に入ると同時に電話が鳴った。","japanese_furigana":"部屋に入ると同時に電話が鳴った。","english":"The telephone rang (literally: at the same time) as I entered the room."}]'::jsonb),
    ('03fcfee0-d0ca-4881-a886-c0ab9334b27c'::uuid,ARRAY['Canonical pattern: 〜と言うか']::text[],ARRAY['Use this construction to express A phrase used to restate what was just said in order to be more accurate or appropriate.. A phrase used to restate what was just said in order to be more accurate or appropriate.']::text[],ARRAY['【Related Expression: と言うより】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"自分の勘違いと言うか、不注意でした。","japanese_furigana":"自分の勘違いと言うか、不注意でした。","english":"It was my misunderstanding . . . or carelessness, rather."},{"japanese":"彼のことは諦めたと言うか、もうどうでもよくなった。","japanese_furigana":"彼のことは諦めたと言うか、もうどうでもよくなった。","english":"I''m through with him. Or rather, I don''t care anymore."}]'::jsonb),
    ('058f6198-7505-4faa-985f-06cb26c21663'::uuid,ARRAY['(i) Noun と言うと']::text[],ARRAY['Use this construction to express A phrase which is used when something which someone has mentioned causes an involuntary response.. A phrase which is used when something which someone has mentioned causes an involuntary response.']::text[],ARRAY['【Related Expression: と言えば】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"サンフランシスコと言うと、あのケーブルカーを思い出す。","japanese_furigana":"サンフランシスコと言うと、あのケーブルカーを思い出す。","english":"When you mention San Francisco, I remember those cable cars."},{"japanese":"日本語を話すと言うと聞こえはいいんですが、実は簡単な挨拶が出来るだけなんです。","japanese_furigana":"日本語を話すと言うと聞こえはいいんですが、実は簡単な挨拶が出来るだけなんです。","english":"It sounds impressive when I say that I can speak Japanese, but the fact is that all I can do is exchange simple greetings."}]'::jsonb),
    ('60116409-6081-4cdf-ac94-b5f8327b407f'::uuid,ARRAY['(i) Sentence1。 と言うのは 、Sentence2。']::text[],ARRAY['Use this construction to express A phrase that introduces the reason for what has just been said.. A phrase that introduces the reason for what has just been said.']::text[],ARRAY['【Related Expression: なぜかと言うと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"来月の旅行は取りやめます。と言うのは、同じ頃に大事なお客が来ることになったんです。","japanese_furigana":"来月の旅行は取りやめます。と言うのは、同じ頃に大事なお客が来ることになったんです。","english":"We are cancelling next month''s trip. I''m saying this because it turns out that we''re going to have an important guest around the same time."},{"japanese":"今まで読めていた画像ファイルがほとんど読めなくなってしまいました。ほとんどと言うのは、少しですが読めるファイルもあるのです。","japanese_furigana":"今まで読めていた画像ファイルがほとんど読めなくなってしまいました。ほとんどと言うのは、少しですが読めるファイルもあるのです。","english":"Almost all the image ﬁles that I have been able to read until now have become unreadable. I say \"almost\" because, even though there are only a few, there are ﬁles that are still readable."}]'::jsonb),
    ('1543eb34-6d91-4410-b580-362314bdfadf'::uuid,ARRAY['(i) Noun と言っても']::text[],ARRAY['Use this construction to express A phrase which is used to clarify a statement in the preceding discourse which might be misleading.. A phrase which is used to clarify a statement in the preceding discourse which might be misleading.']::text[],ARRAY['The core sense is A phrase which is used to clarify a statement in the preceding discourse which might be misleading.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私には子供がいます。子供と言ってももう大学生ですが。","japanese_furigana":"私には子供がいます。子供と言ってももう大学生ですが。","english":"I have a child. Well, although I said, \"child,\" he is already a college student (literally: he is already a college student, though)."},{"japanese":"Ａ：毎日お忙しいんでしょうね。Ｂ：いえ、忙しいと言っても週末は休んでいますから。","japanese_furigana":"Ａ：毎日お忙しいんでしょうね。Ｂ：いえ、忙しいと言っても週末は休んでいますから。","english":"A: You are busy every day, aren''t you? B: No, although people may say that I''m busy, I do not work on weekends, so . . ."}]'::jsonb),
    ('a4dbace0-6d52-4f39-be11-4b94196ded9f'::uuid,ARRAY['Vnegative ないことには ～']::text[],ARRAY['Use this construction to express A phrase that means “if something has not taken place, something else won’t/can’t take place”.. A phrase that means “if something has not taken place, something else won’t/can’t take place”.']::text[],ARRAY['【Related Expression: なくては; なければ; なかったら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この仕事が終わらないことには、家族と旅行に行くこともできない。","japanese_furigana":"この仕事が終わらないことには、家族と旅行に行くこともできない。","english":"If I don''t ﬁnish this work, I can''t go on a trip with my family."},{"japanese":"追加予算が下りないことには、このプロジェクトの遂行は無理だ。","japanese_furigana":"追加予算が下りないことには、このプロジェクトの遂行は無理だ。","english":"Without (money from) an additional budget, it will be impossible to accomplish this project."}]'::jsonb),
    ('cd5ce066-7515-4dbb-bbb0-f4612b4b7395'::uuid,ARRAY['(i) Number1(+Counter) ないし ( は )Number2(+Counter)']::text[],ARRAY['Use this construction to express A particle that presents two possible choices or the minimum and maximum possible numbers/lengths/weights/etc. of something; or a conjunction that links two possible actions or events.. A particle that presents two possible choices or the minimum and maximum possible numbers/lengths/weights/etc. of something; or a conjunction that links two possible actions or events.']::text[],ARRAY['【Related Expression: から; か; または; もしくは; さもなくば; あるいは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このクラスの学生のほとんどは3年ないし（は）4年の日本語学習歴を持っている。","japanese_furigana":"このクラスの学生のほとんどは3年ないし（は）4年の日本語学習歴を持っている。","english":"Most students in this class have three to four years of experience studying Japanese."},{"japanese":"この論文集の論文はすべて日本語（か）ないしは英語で書かれている。","japanese_furigana":"この論文集の論文はすべて日本語（か）ないしは英語で書かれている。","english":"The papers in this collection are written in Japanese or English."}]'::jsonb),
    ('a7d4b6aa-fef0-4209-8339-faf0e74ca3fc'::uuid,ARRAY['Vnegative ないでもない']::text[],ARRAY['Use this construction to express A phrase that indicates the speaker/writer hesitantly feels or expresses that something is the case.. A phrase that indicates the speaker/writer hesitantly feels or expresses that something is the case.']::text[],ARRAY['【Related Expression: ないこともない; なくもない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今が私の人生で一番幸せな時期だという気がしないでもない。","japanese_furigana":"今が私の人生で一番幸せな時期だという気がしないでもない。","english":"I seem to feel that right now is the happiest time of my life."},{"japanese":"あの時大学を辞めたことを、今では少し早まったなと思わないでもない。","japanese_furigana":"あの時大学を辞めたことを、今では少し早まったなと思わないでもない。","english":"Now I rather feel that leaving the university at that time was a bit too hasty."}]'::jsonb),
    ('668deea1-eff5-4883-9cf6-adeb6297a2dc'::uuid,ARRAY['(i) {Vます/Vてい} ながら ( も )']::text[],ARRAY['Use this construction to express A disjunctive conjunction used normally in written Japanese with the meaning of ''although''.. A disjunctive conjunction used normally in written Japanese with the meaning of ''although''.']::text[],ARRAY['【Related Expression: が; けれど(も); のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この部屋は狭いながら（も）居心地がよい。","japanese_furigana":"この部屋は狭いながら（も）居心地がよい。","english":"Although his room is small, it is comfortable."},{"japanese":"山口はそのことを知りながら（も）黙っていた。","japanese_furigana":"山口はそのことを知りながら（も）黙っていた。","english":"Yamaguchi kept silent, although he knew about the matter."}]'::jsonb),
    ('dfd8301d-cc86-410f-8fb7-eb160d66d312'::uuid,ARRAY['Noun なくして ( は )']::text[],ARRAY['Use this construction to express A compound particle meaning “without something”.. A compound particle meaning “without something”.']::text[],ARRAY['【Related Expression: なしに(は); なしで(は)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"努力なくして（は）この事業はできない。","japanese_furigana":"努力なくして（は）この事業はできない。","english":"Without effort we won''t be able to ﬁnish this undertaking."},{"japanese":"山川教授なくしては今の私は存在しなかったであろう。","japanese_furigana":"山川教授なくしては今の私は存在しなかったであろう。","english":"Without Professor Yamakawa, I wouldn''t be what I am now."}]'::jsonb),
    ('4dae5301-7a7d-4d02-8c32-48e913c76e54'::uuid,ARRAY['Sentence。 なぜなら ( ば )～ からだ 。']::text[],ARRAY['Use this construction to express A structure used to introduce a reason for the statement in the preceding sentence.. A structure used to introduce a reason for the statement in the preceding sentence.']::text[],ARRAY['【Related Expression: から; ので; なぜかと言うと~からだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼はみんなに好かれている。なぜなら（ば）、誰にでも親切だからだ。","japanese_furigana":"彼はみんなに好かれている。なぜなら（ば）、誰にでも親切だからだ。","english":"Everybody likes him. The reason is that he is kind to everybody."},{"japanese":"私は自分が好きです。なぜならば、今を自由に生きているからです。","japanese_furigana":"私は自分が好きです。なぜならば、今を自由に生きているからです。","english":"I like myself. The reason is that I am living freely in the moment."}]'::jsonb),
    ('a49cb6a1-953c-435c-8753-9ac8c02496e1'::uuid,ARRAY['(i) {V/Adjective い}informal などと']::text[],ARRAY['Use this construction to express A compound particle that indicates an approximate quote of words or ideas.. A compound particle that indicates an approximate quote of words or ideas.']::text[],ARRAY['The core sense is A compound particle that indicates an approximate quote of words or ideas.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"日本の文化はユニークだなどと言う人がいるが、私はそうは思わない。","japanese_furigana":"日本の文化はユニークだなどと言う人がいるが、私はそうは思わない。","english":"There are people who say things like Japanese culture is unique, but I don''t think so."},{"japanese":"お金がないから、日本へ行くなどということは夢です。","japanese_furigana":"お金がないから、日本へ行くなどということは夢です。","english":"I don''t have money, so ideas like going to Japan are just dreams."}]'::jsonb),
    ('0caba1cb-ea42-4468-9ffe-8f4b87e48d39'::uuid,ARRAY['(i) NP1 ならではの NP2']::text[],ARRAY['Use this construction to express A phrase indicating something is “impossible if it’s not X”.. A phrase indicating something is “impossible if it’s not X”.']::text[],ARRAY['【Related Expression: でなければ; でなくては; でないと; でなかったら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"丸山博士の講演は、一流の科学者ならではの示唆に富む内容だった。","japanese_furigana":"丸山博士の講演は、一流の科学者ならではの示唆に富む内容だった。","english":"Dr. Maruyama''s lecture was rich with suggestion, the likes of which could only be heard from a ﬁrst-class scientist (like himself)."},{"japanese":"四季を通じて美しい景色が楽しめるのはこの地ならではだ。","japanese_furigana":"四季を通じて美しい景色が楽しめるのはこの地ならではだ。","english":"Only here can we enjoy beautiful scenery through all four seasons."}]'::jsonb),
    ('97899e2d-4697-4e5f-a31c-993cd34eda25'::uuid,ARRAY['(i) Adjective (い/な)て ならない']::text[],ARRAY['Use this construction to express A phrase that is used to express insurmountable psychological or physical feelings.. A phrase that is used to express insurmountable psychological or physical feelings.']::text[],ARRAY['【Related Expression: 堪らない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"病気の母のことが心配でならない。","japanese_furigana":"病気の母のことが心配でならない。","english":"I''m very much worried about my sick mother. (Literally: I cannot help worrying about my sick mother)."},{"japanese":"日本の歴史をもっと深く知りたくてならない。","japanese_furigana":"日本の歴史をもっと深く知りたくてならない。","english":"I''m dying to know Japanese history more deeply."}]'::jsonb),
    ('1856c186-87b8-4fdc-b0f0-f90bbb93d39b'::uuid,ARRAY['(i) Noun なり Noun なり {が/を}']::text[],ARRAY['Use this construction to express A phrase to indicate two representative choices/examples.. A phrase to indicate two representative choices/examples.']::text[],ARRAY['【Related Expression: か~か; たり~たり; とか~とか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"文法が分からなかったら、私なり鈴木先生なりに質問しなさい。","japanese_furigana":"文法が分からなかったら、私なり鈴木先生なりに質問しなさい。","english":"If you don''t understand grammar, ask me or Professor Suzuki."},{"japanese":"読めない漢字は辞書を引くなり、日本人に聞くなりしなさい。","japanese_furigana":"読めない漢字は辞書を引くなり、日本人に聞くなりしなさい。","english":"As for kanji you can''t read, find out the reading either by looking it up in a dictionary or by asking a Japanese."}]'::jsonb),
    ('39e4c783-c7c1-4126-999f-25d5ccc2fa09'::uuid,ARRAY['(i) {V/Adjectiveい}informal なんて']::text[],ARRAY['Use this construction to express A colloquial particle used to express a strong feeling such as astonishment, incredulousness, envy, disdain, dislike, happiness, etc.. A colloquial particle used to express a strong feeling such as astonishment, incredulousness, envy, disdain, dislike, happiness, etc.']::text[],ARRAY['【Related Expression: (など)とは; なんか; など】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"小学校からのいじめが中学まで続くなんてひどい。","japanese_furigana":"小学校からのいじめが中学まで続くなんてひどい。","english":"It''s terrible that bullying continues after grade school into junior high."},{"japanese":"最近は電子メールばかり使っていて、手紙なんて滅多に書かない。","japanese_furigana":"最近は電子メールばかり使っていて、手紙なんて滅多に書かない。","english":"Lately I''ve been using only e-mail, and seldom write (a thing like) a letter."}]'::jsonb),
    ('3048843e-02a4-4050-89b9-ae95659dda73'::uuid,ARRAY['V1informal nonpast に V2potential negative Where V1=V2']::text[],ARRAY['Use this construction to express A sentence structure meaning “someone cannot manage to do something”. A sentence structure meaning “someone cannot manage to do something”']::text[],ARRAY['【Related Expression: たくても~ない; たくとも~ない; ようにも~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"後任者が決まらないので、辞めるに辞められない。","japanese_furigana":"後任者が決まらないので、辞めるに辞められない。","english":"Because my successor hasn''t been chosen yet, I haven''t been able to resign (my current position)."},{"japanese":"大事なお客さんからの電話がいつまで待ってもかかってこないので、帰るに帰れない。","japanese_furigana":"大事なお客さんからの電話がいつまで待ってもかかってこないので、帰るに帰れない。","english":"I''ve been waiting a long time for a call from an important customer, but it hasn''t come, so I cannot leave the ofﬁce."}]'::jsonb),
    ('23d20996-476e-407c-8d36-3c34db20aad2'::uuid,ARRAY['Canonical pattern: 〜に（も）なく']::text[],ARRAY['Use this construction to express A phrase that means something unusual happens or someone does something unusual.. A phrase that means something unusual happens or someone does something unusual.']::text[],ARRAY['The core sense is A phrase that means something unusual happens or someone does something unusual.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"彼女は今日はいつに（も）なく陽気だった。","japanese_furigana":"彼女は今日はいつに（も）なく陽気だった。","english":"She was unusually cheerful today."},{"japanese":"宏は「ただいまー」といつになく明るい声で帰ってきた。","japanese_furigana":"宏は「ただいまー」といつになく明るい声で帰ってきた。","english":"Hiroshi came home and said \"I''m home!\" in an unusually cheerful voice."}]'::jsonb),
    ('217a700a-2df1-4add-b0da-b6651c76574b'::uuid,ARRAY['Canonical pattern: 〜に（動作主・起点）']::text[],ARRAY['Use this construction to express A particle that indicates an agent or a source in passive, causative, もらう/てまらう and other receiving constructions.. A particle that indicates an agent or a source in passive, causative, もらう/てまらう and other receiving constructions.']::text[],ARRAY['【Related Expression: から1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"一男は友達に手紙を読まれた・読まれました。","japanese_furigana":"一男は友達に手紙を読まれた・読まれました。","english":"Kazuo''s friend read Kazuo''s letter (and Kazuo was unhappy)."},{"japanese":"秋子は浩にご飯を作らせた・作らせました。","japanese_furigana":"秋子は浩にご飯を作らせた・作らせました。","english":"Akiko made Hiroshi fix a meal."}]'::jsonb),
    ('03b86b4a-064e-427d-9f5b-e90a8cbf0716'::uuid,ARRAY['Canonical pattern: 〜に（存在場所）']::text[],ARRAY['Use this construction to express A particle which indicates the location where someone or something exists.. A particle which indicates the location where someone or something exists.']::text[],ARRAY['【Related Expression: で1; に4】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ヒルさんは今ジョンソンさんのアパートにいる・います。","japanese_furigana":"ヒルさんは今ジョンソンさんのアパートにいる・います。","english":"Mr. Hill is at Mr. Johnson''s apartment now."},{"japanese":"私のクラスには中国人の学生がいる・います。","japanese_furigana":"私のクラスには中国人の学生がいる・います。","english":"There is a Chinese student in my class."}]'::jsonb),
    ('c1201892-ea6e-4c5f-8b37-274c758fff1e'::uuid,ARRAY['Canonical pattern: 〜に（接触面）']::text[],ARRAY['Use this construction to express A particle that indicates the surface of something upon which some action directly takes place.. A particle that indicates the surface of something upon which some action directly takes place.']::text[],ARRAY['【Related Expression: で1; へ (まで, に7); に6】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"子供は紙に絵を書いた・書きました。","japanese_furigana":"子供は紙に絵を書いた・書きました。","english":"A child has drawn a picture on the paper."},{"japanese":"ここにあなたの名前と住所を書いて下さい。","japanese_furigana":"ここにあなたの名前と住所を書いて下さい。","english":"Please write your name and address here."}]'::jsonb),
    ('f63d4185-1e1a-4dc3-bfe7-44579cba4554'::uuid,ARRAY['Canonical pattern: 〜に（時点）']::text[],ARRAY['Use this construction to express A particle that indicates a point of time at which something takes place.. A particle that indicates a point of time at which something takes place.']::text[],ARRAY['【Related Expression: で4】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は毎朝六時半に起きる・起きます。","japanese_furigana":"私は毎朝六時半に起きる・起きます。","english":"I get up at six thirty every morning."},{"japanese":"私は四月一日に生まれました。","japanese_furigana":"私は四月一日に生まれました。","english":"I was born on April 1st."}]'::jsonb),
    ('cf656ae2-ee43-4b97-a147-7354f7b08996'::uuid,ARRAY['Canonical pattern: 〜に（移動先）']::text[],ARRAY['Use this construction to express A particle which indicates a place toward which someone or something moves.. A particle which indicates a place toward which someone or something moves.']::text[],ARRAY['【Related Expression: へ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はきのうサンフランシスコに行った・行きました。","japanese_furigana":"私はきのうサンフランシスコに行った・行きました。","english":"I went to San Francisco yesterday."},{"japanese":"ジムは来年アメリカに帰る。","japanese_furigana":"ジムは来年アメリカに帰る。","english":"Jim is going back to America next year."}]'::jsonb),
    ('bbc8f99e-c0d3-488f-a57a-44729845ff8d'::uuid,ARRAY['Vます に']::text[],ARRAY['Use this construction to express A particle which indicates purpose when someone moves from one place to another.. A particle which indicates purpose when someone moves from one place to another.']::text[],ARRAY['【Related Expression: 為に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はデパートへ贈り物を買いに行った・行きました。","japanese_furigana":"私はデパートへ贈り物を買いに行った・行きました。","english":"I went to a department store to buy a gift"},{"japanese":"学生が質問をしに来た。","japanese_furigana":"学生が質問をしに来た。","english":"A student came to ask questions."}]'::jsonb),
    ('d3d50c32-bc20-4bc7-9450-2d9defefefd5'::uuid,ARRAY['(i) {Verb/Adjective い}informal {でしょう/だろう} に']::text[],ARRAY['Use this construction to express A sentence final particle that expresses the speaker''s feeling of great regret or sympathy.. A sentence final particle that expresses the speaker''s feeling of great regret or sympathy.']::text[],ARRAY['【Related Expression: のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"昨日来れば夏子に会えたでしょう・だろうに。","japanese_furigana":"昨日来れば夏子に会えたでしょう・だろうに。","english":"If you had come here yesterday, you could have met Natsuko."},{"japanese":"老人が一人で暮らすのはさぞ寂しいでしょう・だろうに。","japanese_furigana":"老人が一人で暮らすのはさぞ寂しいでしょう・だろうに。","english":"It must be lonely for an old man to live alone."}]'::jsonb),
    ('ea672e37-1bd5-4471-9012-b7afa2436526'::uuid,ARRAY['Canonical pattern: 〜に（間接目的語）']::text[],ARRAY['Use this construction to express An indirect object marker.. An indirect object marker.']::text[],ARRAY['The core sense is An indirect object marker.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は母に手紙をよく書く・書きます。","japanese_furigana":"私は母に手紙をよく書く・書きます。","english":"I often write letters to my mother."},{"japanese":"父は僕に時計を呉れた。","japanese_furigana":"父は僕に時計を呉れた。","english":"My father gave me a watch."}]'::jsonb),
    ('30ac4e2b-602c-47cc-9536-9404a237d52b'::uuid,ARRAY['(i) Noun { に / と } もなると']::text[],ARRAY['Use this construction to express A phrase that is used when something or some situation is perceived to be special.. A phrase that is used when something or some situation is perceived to be special.']::text[],ARRAY['【Related Expression: に/ともなれば】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"桜の季節｛に/と｝もなるとこの公園は花見客でにぎわう。","japanese_furigana":"桜の季節｛に/と｝もなるとこの公園は花見客でにぎわう。","english":"In the cherry blossom season (literally: When it becomes the cherry blossom season), this park is packed with cherry blossom viewers."},{"japanese":"外国へ行くともなると、その国の言語や文化を勉強したくなるはずだ。","japanese_furigana":"外国へ行くともなると、その国の言語や文化を勉強したくなるはずだ。","english":"When you go abroad, most likely you will want to study that country''s language and culture."}]'::jsonb),
    ('e4680d20-12af-4ff1-bb8c-60fba47bfc89'::uuid,ARRAY['Noun にいたっては']::text[],ARRAY['Use this construction to express A compound particle that indicates an extreme example.. A compound particle that indicates an extreme example.']::text[],ARRAY['【Related Expression: の場合(は); ときたら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"人間の体は60%が水、魚は75%、くらげにいたっては96%が水だ。","japanese_furigana":"人間の体は60%が水、魚は75%、くらげにいたっては96%が水だ。","english":"Human bodies are 60 percent water, while ﬁsh are 75 percent water. As for jellyﬁsh, the ﬁgure is 96 percent."},{"japanese":"私自身は社会人になってからコンピュータを使い始めたが、新入社員は中学生の頃から、私の子供たちにいたっては、生まれた時から家にコンピュータがある世代だ。","japanese_furigana":"私自身は社会人になってからコンピュータを使い始めたが、新入社員は中学生の頃から、私の子供たちにいたっては、生まれた時から家にコンピュータがある世代だ。","english":"I myself started to use a computer after I graduated and got a job, but the new hires got started on computers when they were still junior high school students. As for my children, they belong to the generation for whom a computer is available at home from the time of their birth."}]'::jsonb),
    ('1511d706-e110-44d2-9b4b-7fd1b4b9547f'::uuid,ARRAY['(i) Noun において']::text[],ARRAY['Use this construction to express A compound particle which indicates the place of an action/event, a state or time.. A compound particle which indicates the place of an action/event, a state or time.']::text[],ARRAY['【Related Expression: で; に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"来年の総会はシカゴのヒルトン・ホテルにおいて行われる。","japanese_furigana":"来年の総会はシカゴのヒルトン・ホテルにおいて行われる。","english":"Next year''s general meeting will be held at the Hilton Hotel in Chicago."},{"japanese":"コンピュータは近い将来においてほとんどの家庭に行き渡るだろう。","japanese_furigana":"コンピュータは近い将来においてほとんどの家庭に行き渡るだろう。","english":"Computers will probably spread to almost every household in the near future."}]'::jsonb),
    ('b584dacc-bf90-4c3b-98cc-b6f009c9f6da'::uuid,ARRAY['(i) Noun に関わらず']::text[],ARRAY['Use this construction to express A compound particle that means “regardless of”. A compound particle that means “regardless of”']::text[],ARRAY['【Related Expression: を問わず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"当社は性別に関わらず同様に昇進できます。","japanese_furigana":"当社は性別に関わらず同様に昇進できます。","english":"At this company, employees are (literally: you can be) promoted equally, regardless of sex."},{"japanese":"出席か欠席かに関わらず同封の葉書でお知らせ下さい。","japanese_furigana":"出席か欠席かに関わらず同封の葉書でお知らせ下さい。","english":"Whether or not you will attend, please inform us (of your intention) using the enclosed postcard."}]'::jsonb),
    ('1d6d5738-6e5f-4bc5-8464-94c283351a36'::uuid,ARRAY['Noun にかけては']::text[],ARRAY['Use this construction to express A compound particle that marks something in which someone excels or has conﬁdence.. A compound particle that marks something in which someone excels or has conﬁdence.']::text[],ARRAY['【Related Expression: については; に関しては; では】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"経済学のノーベル賞を受賞したジョン・ナシュは数学にかけては自分の右に出る者はいないと思っていた。","japanese_furigana":"経済学のノーベル賞を受賞したジョン・ナシュは数学にかけては自分の右に出る者はいないと思っていた。","english":"John Nash, who received a Nobel Prize in economics, thought that when it came to math, nobody was better than he was."},{"japanese":"ジャッキー・チェンは、アクションにかけては右に出る者がいない俳優である。","japanese_furigana":"ジャッキー・チェンは、アクションにかけては右に出る者がいない俳優である。","english":"Jackie Chan is an actor with whom none can compete when it comes to action ﬁlms."}]'::jsonb),
    ('b4faf3c9-2303-48d0-9440-420571a58f88'::uuid,ARRAY['VN に難くない Where VN=Sino-Japanese compound']::text[],ARRAY['Use this construction to express A phrase that indicates that it is not hard to imagine or guess a situation.. A phrase that indicates that it is not hard to imagine or guess a situation.']::text[],ARRAY['The core sense is A phrase that indicates that it is not hard to imagine or guess a situation.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"給料が低いために教師の質が低下した（であろう）ことは想像にかたくない。","japanese_furigana":"給料が低いために教師の質が低下した（であろう）ことは想像にかたくない。","english":"It is not hard to imagine that the quality of teachers fell because of the low salary."},{"japanese":"幼い時に両親を失った彼女の生活が｛いかに/どれほど｝悲惨だったかは推測にかたくない。","japanese_furigana":"幼い時に両親を失った彼女の生活が｛いかに/どれほど｝悲惨だったかは推測にかたくない。","english":"It is easy to guess how miserable her life was after she lost her parents."}]'::jsonb),
    ('41c02383-adbe-4dce-af3f-b09bee8c93e1'::uuid,ARRAY['Noun にしたところで']::text[],ARRAY['Use this construction to express A compound particle that means “even” or “also”.. A compound particle that means “even” or “also”.']::text[],ARRAY['【Related Expression: でも; も; にしてからが】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼は日本語を20年も勉強しているが、その彼にしたところで、まだ分からない文法に時々出くわすそうだ。","japanese_furigana":"彼は日本語を20年も勉強しているが、その彼にしたところで、まだ分からない文法に時々出くわすそうだ。","english":"He has studied Japanese for 20 years, but he told me that even he still encounters grammar he doesn''t understand."},{"japanese":"子供はいつか手の届かないところへ行ってしまうものだ。自分の子だけはそうでないと思うかもしれないが、あなたの子にしたところで同じだ。","japanese_furigana":"子供はいつか手の届かないところへ行ってしまうものだ。自分の子だけはそうでないと思うかもしれないが、あなたの子にしたところで同じだ。","english":"Children go (places) beyond their parents'' reach sooner or later. You may think that your own children will be different, but they, too, will be the same."}]'::jsonb),
    ('ce981808-a62e-4268-9da5-cfa0e6048367'::uuid,ARRAY['(i) Adjectiveなstem にして']::text[],ARRAY['Use this construction to express A conjunction meaning “and” that is used to combine two noun phrases or な-adjectives.. A conjunction meaning “and” that is used to combine two noun phrases or な-adjectives.']::text[],ARRAY['【Related Expression: で】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女は頭脳明晰にして端麗な秘書である。","japanese_furigana":"彼女は頭脳明晰にして端麗な秘書である。","english":"She is a bright and also beautiful secretary."},{"japanese":"彼は偉大な学者にして優れた教育者でもあった。","japanese_furigana":"彼は偉大な学者にして優れた教育者でもあった。","english":"He was both a distinguished scholar and an excellent educator."}]'::jsonb),
    ('09b64db3-83ab-4eb2-95d6-92b5f27fece3'::uuid,ARRAY['(i) Number+Counter にして']::text[],ARRAY['Use this construction to express A compound particle that indicates a period of time/stage (in life) at which some surprising action or state takes place.. A compound particle that indicates a period of time/stage (in life) at which some surprising action or state takes place.']::text[],ARRAY['【Related Expression: で】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"過度の恐怖や心労が一夜にして白髪をつくる。","japanese_furigana":"過度の恐怖や心労が一夜にして白髪をつくる。","english":"Excessive fear and worry will make your hair turn grey overnight."},{"japanese":"彼女は45歳にして初めて子供ができた。","japanese_furigana":"彼女は45歳にして初めて子供ができた。","english":"She had her ﬁrst child at the age of 45."}]'::jsonb),
    ('4a4f12e8-06d4-42cb-ba37-c962ed346a4e'::uuid,ARRAY['Noun にしてからが']::text[],ARRAY['Use this construction to express A compound particle indicating that something unexpected occurs.. A compound particle indicating that something unexpected occurs.']::text[],ARRAY['【Related Expression: でさえ; ですら; からして; にしたところで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ワールドカップの時はサッカーファンでもない私にしてからが興奮状態でした。","japanese_furigana":"ワールドカップの時はサッカーファンでもない私にしてからが興奮状態でした。","english":"I am not a soccer fan, but during the World Cup, even I got excited."},{"japanese":"警察にしてからが、いざ事件が起きないと市民を暴力から守ってくれない。","japanese_furigana":"警察にしてからが、いざ事件が起きないと市民を暴力から守ってくれない。","english":"Even the police don''t protect citizens from violence unless an incident actually occurs."}]'::jsonb),
    ('403f4c4f-84a8-458a-9d74-05a091f180b1'::uuid,ARRAY['(i) Noun ( だった ) にしては']::text[],ARRAY['Use this construction to express A phrase that indicates a generally agreed upon standard (the entire sentence that includes this phrase expresses some deviation from that standard.). A phrase that indicates a generally agreed upon standard (the entire sentence that includes this phrase expresses some deviation from that standard.)']::text[],ARRAY['【Related Expression: としては】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"高山さんは日本人にしては大きい・大きいです。","japanese_furigana":"高山さんは日本人にしては大きい・大きいです。","english":"Mr. Takayama is big for a Japanese person."},{"japanese":"ボブは日本語をよく勉強しているにしては下手だ・下手です。","japanese_furigana":"ボブは日本語をよく勉強しているにしては下手だ・下手です。","english":"Considering that Bob is studying Japanese hard, he is poor at it."}]'::jsonb),
    ('6f4ee887-924f-45b7-9cc8-c4712cd4836f'::uuid,ARRAY['(i) Vinformal に { しろ / せよ }']::text[],ARRAY['Use this construction to express A conjunctive phrase that carries the meaning of concession.. A conjunctive phrase that carries the meaning of concession.']::text[],ARRAY['【Related Expression: にしても; としても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"時間があまりなかったに｛しろ/せよ｝、この仕事はひどすぎる。","japanese_furigana":"時間があまりなかったに｛しろ/せよ｝、この仕事はひどすぎる。","english":"Even though he didn''t have much time, this work is too sloppy."},{"japanese":"誰が書くに｛しろ/せよ｝、絶対間違いがあってはいけない。","japanese_furigana":"誰が書くに｛しろ/せよ｝、絶対間違いがあってはいけない。","english":"No matter who writes it, there can be absolutely no mistakes."}]'::jsonb),
    ('1e3a0cf4-e6dd-4f32-bd19-5960e9b35141'::uuid,ARRAY['Number+Counter につき']::text[],ARRAY['Use this construction to express A compound particle which expresses a rate or ratio.. A compound particle which expresses a rate or ratio.']::text[],ARRAY['【Related Expression: あたり】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この仕事は一時間につき六ドル貰える。","japanese_furigana":"この仕事は一時間につき六ドル貰える。","english":"This job will pay you six dollars an hour. (literally: You can get six dollars an hour doing this job.)"},{"japanese":"一冊につき百五十円の送料が要ります。","japanese_furigana":"一冊につき百五十円の送料が要ります。","english":"A hundred and fifty yen is necessary per copy for postage. (literally: Postage of one hundred and fifty yen is necessary per copy.)"}]'::jsonb),
    ('a2e8fc1f-1c6f-404a-8420-7b37efbb660f'::uuid,ARRAY['(i) Vinformal nonpast につれて']::text[],ARRAY['Use this construction to express A phrase used to indicate that a change occurs in accordance with another simultaneous change.. A phrase used to indicate that a change occurs in accordance with another simultaneous change.']::text[],ARRAY['【Related Expression: に従って/従い; ば~ほど; と共に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語が上達するにつれて日本人の友達が増えた。","japanese_furigana":"日本語が上達するにつれて日本人の友達が増えた。","english":"As my Japanese became more proficient, the number of my Japanese friends increased."},{"japanese":"時代の変化につれて、文化も変わっていく。","japanese_furigana":"時代の変化につれて、文化も変わっていく。","english":"Culture also changes with the change of the times."}]'::jsonb),
    ('c2c9286c-3252-4e7f-a03c-af0bf478927f'::uuid,ARRAY['(i) Noun(だけ) にとどまらず']::text[],ARRAY['Use this construction to express A phrase indicating that something goes beyond a spatial/temporal boundary.. A phrase indicating that something goes beyond a spatial/temporal boundary.']::text[],ARRAY['【Related Expression: だけで(は)なく~(も); のにならず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼の研究範囲は哲学(だけ)にとどまらず、認知心理学の領域にまで広がっている。","japanese_furigana":"彼の研究範囲は哲学(だけ)にとどまらず、認知心理学の領域にまで広がっている。","english":"His area of research is not limited merely to philosophy, but extends to cognitive psychology as well."},{"japanese":"彼女は小説を広く読む(だけ)にとどまらず、自分でもいくつか書いて、すでに雑誌に発表している。","japanese_furigana":"彼女は小説を広く読む(だけ)にとどまらず、自分でもいくつか書いて、すでに雑誌に発表している。","english":"Not only does she avidly read novels, she also has written a couple of novels herself, which have been published in magazines."}]'::jsonb),
    ('0bfd1cf0-c9ed-432c-8600-17a145590052'::uuid,ARRAY['(i) Noun (time) になると']::text[],ARRAY['Use this construction to express A phrase that expresses the time when an uncontrollable state or a habitual action occurs.. A phrase that expresses the time when an uncontrollable state or a habitual action occurs.']::text[],ARRAY['The core sense is A phrase that expresses the time when an uncontrollable state or a habitual action occurs.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"夏になると、摂氏三十度を越す日が多いです。","japanese_furigana":"夏になると、摂氏三十度を越す日が多いです。","english":"In summer (literally: When it becomes summer), there are many days that exceed 30 degrees Celsius."},{"japanese":"父は食べ物のことになると、とてもやかましかった。","japanese_furigana":"父は食べ物のことになると、とてもやかましかった。","english":"When it comes to the matter of food, my father was very particular."}]'::jsonb),
    ('41d6840b-6dc9-4a30-93d8-159b686831f4'::uuid,ARRAY['(i) {Noun/Demonstrative pronoun} にひきかえ']::text[],ARRAY['Use this construction to express A phrase that indicates a sharp contrast.. A phrase that indicates a sharp contrast.']::text[],ARRAY['【Related Expression: に比べると/比べて; 代わりに; に対して】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"几帳面な父にひきかえ、息子はだらしなかった。","japanese_furigana":"几帳面な父にひきかえ、息子はだらしなかった。","english":"The son, in contrast to his meticulous father, was slovenly."},{"japanese":"この大学は教育の質がとてもいいのにひきかえ、学内の設備が劣る。","japanese_furigana":"この大学は教育の質がとてもいいのにひきかえ、学内の設備が劣る。","english":"While the quality of education at this college is excellent, the quality of the campus facilities is inferior."}]'::jsonb),
    ('c72099d8-f838-4572-8f2b-9ff21528e512'::uuid,ARRAY['(i) (Nounは)Noun にはかならない']::text[],ARRAY['Use this construction to express A phrase that is used to indicate that an action/state mentioned in the topic phrase or clause is nothing but something.. A phrase that is used to indicate that an action/state mentioned in the topic phrase or clause is nothing but something.']::text[],ARRAY['【Related Expression: に過ぎない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あの人の言葉は美辞麗句にほかならない。","japanese_furigana":"あの人の言葉は美辞麗句にほかならない。","english":"His words are nothing but flowery words."},{"japanese":"日本語を勉強しているのは将来日本で仕事をしたいからにほかならない。","japanese_furigana":"日本語を勉強しているのは将来日本で仕事をしたいからにほかならない。","english":"The reason that I am studying Japanese is simply because I want to work in Japan in the future."}]'::jsonb),
    ('0243a08b-eeaf-4f6d-879e-767598c5c4a6'::uuid,ARRAY['(i) Noun によって']::text[],ARRAY['Use this construction to express A particle that indicates means, cause, agent of passive sentence, or dependency on a situation.. A particle that indicates means, cause, agent of passive sentence, or dependency on a situation.']::text[],ARRAY['【Related Expression: に; で; の為に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"漢和辞典によって知らない漢字を調べる。","japanese_furigana":"漢和辞典によって知らない漢字を調べる。","english":"We examine unknown kanji with a Chinese character dictionary."},{"japanese":"先生によって、勿論、教え方が違います。","japanese_furigana":"先生によって、勿論、教え方が違います。","english":"Teaching methods are, of course, different, depending on the teacher."}]'::jsonb),
    ('27abb516-ddac-47d6-b6c3-e16ef5974621'::uuid,ARRAY['(i) Noun によらず']::text[],ARRAY['Use this construction to express A compound particle that means “without depending on”.. A compound particle that means “without depending on”.']::text[],ARRAY['【Related Expression: なしで; によって/より; を問わず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"リストラによらず(に)この会社を救う方法はない。","japanese_furigana":"リストラによらず(に)この会社を救う方法はない。","english":"There is no way to save this company without restructuring it."},{"japanese":"この会社では学歴によらず、実力があればどんどん大きい仕事をまかされる。","japanese_furigana":"この会社では学歴によらず、実力があればどんどん大きい仕事をまかされる。","english":"At this company, if you are capable, you will be given big assignments one after another, regardless of your educational qualiﬁcations."}]'::jsonb),
    ('623f2e7c-8385-4a35-bca8-38100e202a1d'::uuid,ARRAY['Noun によると']::text[],ARRAY['Use this construction to express A compound particle that is used to identify the source of information provided in the sentence.. A compound particle that is used to identify the source of information provided in the sentence.']::text[],ARRAY['【Related Expression: によれば】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"その温泉は旅行雑誌によると神経痛にいいそうだ。","japanese_furigana":"その温泉は旅行雑誌によると神経痛にいいそうだ。","english":"One of the travel magazines said that hot springs are good for arthritis."},{"japanese":"日本の法律によるとおおむね12歳未満の者は逮捕の対象にならない。","japanese_furigana":"日本の法律によるとおおむね12歳未満の者は逮捕の対象にならない。","english":"According to Japanese law, generally, youths under 12 are not subject to arrest."}]'::jsonb),
    ('f04df975-22d8-49b8-b910-e7ff7ecbccba'::uuid,ARRAY['(i) Noun にわたって']::text[],ARRAY['Use this construction to express A compound particle indicating that something takes place over a particular span of time or physical space.. A compound particle indicating that something takes place over a particular span of time or physical space.']::text[],ARRAY['【Related Expression: にかけて】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"オリンピックが16日間にわたって開かれた。","japanese_furigana":"オリンピックが16日間にわたって開かれた。","english":"The Olympic Games were held for sixteen days."},{"japanese":"干ばつのため広範囲にわたって作物が被害を受けた。","japanese_furigana":"干ばつのため広範囲にわたって作物が被害を受けた。","english":"Due to the drought, crops were damaged over a wide area."}]'::jsonb),
    ('8651e4fc-6d73-4b90-96aa-ababd63e94d5'::uuid,ARRAY['Noun に代わって']::text[],ARRAY['Use this construction to express A compound particle to express replacement or substitution of a regular person/thing by someone/something.. A compound particle to express replacement or substitution of a regular person/thing by someone/something.']::text[],ARRAY['【Related Expression: 代わりに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"病気の山田先生に代わって、鈴木先生が教えて下さった。","japanese_furigana":"病気の山田先生に代わって、鈴木先生が教えて下さった。","english":"In place of Professor Yamada, who is ill, Professor Suzuki taught us."},{"japanese":"戦後ガラスに代わってプラスチックが出てきた。","japanese_furigana":"戦後ガラスに代わってプラスチックが出てきた。","english":"After the war plastics became available replacing glass."}]'::jsonb),
    ('0f933811-ec02-4eee-a2ab-ddf6536ed068'::uuid,ARRAY['(i) Noun に向けて']::text[],ARRAY['Use this construction to express A compound particle that indicates the destination/direction of movement, the target/direction of an action, or the goal/purpose of an action.. A compound particle that indicates the destination/direction of movement, the target/direction of an action, or the goal/purpose of an action.']::text[],ARRAY['【Related Expression: に向かって; をめざして; を目標; の為に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"報道班は次の目的地に向けて出発した。","japanese_furigana":"報道班は次の目的地に向けて出発した。","english":"The team of reporters left for the next destination."},{"japanese":"このテレビコマーシャルは20、30代の独身女性に向けて発信されている。","japanese_furigana":"このテレビコマーシャルは20、30代の独身女性に向けて発信されている。","english":"This TV commercial is being marketed to single women in their twenties and thirties."}]'::jsonb),
    ('d1c81e8c-12fa-4855-98a0-4237ee24fff7'::uuid,ARRAY['(i) Noun に { 当たって / 当たり }']::text[],ARRAY['Use this construction to express A compound particle that indicates occasion of doing something or of having done something in formal Japanese.. A compound particle that indicates occasion of doing something or of having done something in formal Japanese.']::text[],ARRAY['【Related Expression: 前に; に際して; 際(に); 時】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"新入社員の入社に{当たって/当たり}社長はホテルでパーティーを開いた。","japanese_furigana":"新入社員の入社に{当たって/当たり}社長はホテルでパーティーを開いた。","english":"On the occasion of new employees'' entering the company, the president threw a party at a hotel."},{"japanese":"和也は大学を卒業するに{当たって/当たり}、指導教官に今後の進路について相談した。","japanese_furigana":"和也は大学を卒業するに{当たって/当たり}、指導教官に今後の進路について相談した。","english":"On the occasion of graduating from college, Kazuya consulted with his academic adviser on his future direction."}]'::jsonb),
    ('58160fe5-3dff-4413-8833-07a0bcdd53b2'::uuid,ARRAY['(i) Noun に応じて']::text[],ARRAY['Use this construction to express A compound particle that means “in response to”.. A compound particle that means “in response to”.']::text[],ARRAY['【Related Expression: によって; 次第で; いかんで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"組合の要求に応じて標準就業時間が短縮されることになった。","japanese_furigana":"組合の要求に応じて標準就業時間が短縮されることになった。","english":"In response to union demands, the standard work day (literally: standard work hours) will be shortened."},{"japanese":"業績に応じて従業員全員にボーナスが支給された。","japanese_furigana":"業績に応じて従業員全員にボーナスが支給された。","english":"Bonuses were distributed to all employees according to their performance (literally: achievements)."}]'::jsonb),
    ('3fee08a5-292b-4703-a952-655b02ee2168'::uuid,ARRAY['(i) {V/Adjectiveい}informal に決まっている']::text[],ARRAY['Use this construction to express A phrase indicating the speaker’s/writer’s strong conviction or motivation.. A phrase indicating the speaker’s/writer’s strong conviction or motivation.']::text[],ARRAY['【Related Expression: に違いない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"性格は、いい方がいいに決まっている。","japanese_furigana":"性格は、いい方がいいに決まっている。","english":"It is a given that a good personality is preferable."},{"japanese":"お客さまだって安く買いたいに決まっているじゃないか。","japanese_furigana":"お客さまだって安く買いたいに決まっているじゃないか。","english":"Of course customers want to buy things cheaply."}]'::jsonb),
    ('2e2e06f4-cb8e-4f60-b563-d16fc75218ca'::uuid,ARRAY['(i) Adjectiveいinformal nonpast に越したことはない']::text[],ARRAY['Use this construction to express A phrase used to indicate that a state or action is more desirable.. A phrase used to indicate that a state or action is more desirable.']::text[],ARRAY['【Related Expression: ば~ほどよい/いい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"仲間は多いに越したことはない。","japanese_furigana":"仲間は多いに越したことはない。","english":"The more buddies you have the better."},{"japanese":"元気（である）に越したことはない。","japanese_furigana":"元気（である）に越したことはない。","english":"The healthier the better."}]'::jsonb),
    ('04468199-b857-4031-a2f9-ac79405b499f'::uuid,ARRAY['Noun に限って']::text[],ARRAY['Use this construction to express A compound particle to show that only X is different from others.. A compound particle to show that only X is different from others.']::text[],ARRAY['The core sense is A compound particle to show that only X is different from others.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"うちの子供に限ってそんなひどいことはしませんよ。","japanese_furigana":"うちの子供に限ってそんなひどいことはしませんよ。","english":"Our child, of all children, would not do such a terrible thing."},{"japanese":"中野先生はたいてい研究室にいらっしゃるのに、今日に限っていらっしゃらなかった。","japanese_furigana":"中野先生はたいてい研究室にいらっしゃるのに、今日に限っていらっしゃらなかった。","english":"Professor Nakano is usually in his office, but today, of all days, he wasn''t there."}]'::jsonb),
    ('a366c42f-3fb6-41e8-9c0c-3aaa8834a2ed'::uuid,ARRAY['Canonical pattern: 〜ね']::text[],ARRAY['Use this construction to express A sentence final particle that indicates the speaker’s request for confirmation or agreement from the hearer about some shared knowledge.. A sentence final particle that indicates the speaker’s request for confirmation or agreement from the hearer about some shared knowledge.']::text[],ARRAY['The core sense is A sentence final particle that indicates the speaker’s request for confirmation or agreement from the hearer about some shared knowledge.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"坂本さんは煙草を吸わない・吸いませんね。","japanese_furigana":"坂本さんは煙草を吸わない・吸いませんね。","english":"Mr. Sakamoto doesn''t smoke, does he? / Mr. Sakamoto, you don''t smoke, do you?"},{"japanese":"A:今日はいい天気ですね。 B:本当にそうですね。","japanese_furigana":"A:今日はいい天気ですね。 B:本当にそうですね。","english":"A: Today is a fine day, isn''t it? B: Isn''t it!"}]'::jsonb),
    ('e9b52877-e1cf-4235-94c7-f2f1e4bd9040'::uuid,ARRAY['Vinformal negative ねばならない']::text[],ARRAY['Use this construction to express A phrase that indicates duty, obligation or necessity.. A phrase that indicates duty, obligation or necessity.']::text[],ARRAY['【Related Expression: なければならない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本を知るためには一度は日本へ行かねばならない。","japanese_furigana":"日本を知るためには一度は日本へ行かねばならない。","english":"In order to know Japan one has to go to Japan at least once."},{"japanese":"日本は市場をもっと広く開放せねばならない。","japanese_furigana":"日本は市場をもっと広く開放せねばならない。","english":"Japan has to open its market wider."}]'::jsonb),
    ('7c26dafa-4d83-4d22-854a-485f81e852b4'::uuid,ARRAY['(i) X(affirmation) の X(negative) のと']::text[],ARRAY['Use this construction to express A structure that states what is said by someone in order to express the speaker’s disagreement or dissatisfaction.. A structure that states what is said by someone in order to express the speaker’s disagreement or dissatisfaction.']::text[],ARRAY['【Related Expression: とか~とか; だの~だのと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"やったのやらなかったのといつまで言っていても仕方がない。","japanese_furigana":"やったのやらなかったのといつまで言っていても仕方がない。","english":"It is no use talking endlessly about what you did or didn''t do."},{"japanese":"いつまでも好きだの嫌いだのと言っていないで、早く結婚相手を決めなさい。","japanese_furigana":"いつまでも好きだの嫌いだのと言っていないで、早く結婚相手を決めなさい。","english":"You should decide who you want to marry soon without saying all the time that you like (this one) or that you don''t like (that one)."}]'::jsonb)
), invalid as (
  select grammar_id from enrichment where not public.repository_reference_examples_valid(examples_value)
)
select case when count(*)=0 then true else false end as payloads_valid from invalid;

with enrichment(grammar_id,formation_value,usage_value,nuance_value,examples_value) as (
  values
    ('730e64d5-172e-49a3-8307-430e6926b374'::uuid,ARRAY['Sinformal であろう']::text[],ARRAY['Use this construction to express An auxiliary which indicates the writer''s conjecture which is not based on any particular information or evidence.. An auxiliary which indicates the writer''s conjecture which is not based on any particular information or evidence.']::text[],ARRAY['【Related Expression: だろう; まい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本経済は今後も成長を続けるであろう。","japanese_furigana":"日本経済は今後も成長を続けるであろう。","english":"The Japanese economy will probably still keep growing (literally: from now on, too)."},{"japanese":"このようなブームはもう二度と起こらないであろう。","japanese_furigana":"このようなブームはもう二度と起こらないであろう。","english":"Such a boom will probably not happen again."}]'::jsonb),
    ('29a0ce75-d5ab-4811-b75a-c0cf2b6c84d6'::uuid,ARRAY['(i) Verb てはいられない']::text[],ARRAY['Use this construction to express A phrase that is used when someone cannot be doing something or be in some state due to a given situation.. A phrase that is used when someone cannot be doing something or be in some state due to a given situation.']::text[],ARRAY['【Related Expression: ずにはいられない; わけにはいかない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"将来のことを考えると、いつまでもこんな仕事をしてはいられない。","japanese_furigana":"将来のことを考えると、いつまでもこんな仕事をしてはいられない。","english":"When I think about the future, (I realise) I can''t keep doing this kind of work forever."},{"japanese":"彼女があまりにも自分勝手だったので、一言言わないではいられなかった。","japanese_furigana":"彼女があまりにも自分勝手だったので、一言言わないではいられなかった。","english":"Because she was acting so selﬁshly, I couldn''t resist saying something to her."}]'::jsonb),
    ('1650b48a-7aab-4240-9c28-b643cadd0c39'::uuid,ARRAY['(i) Vて ばかりはいられない']::text[],ARRAY['Use this construction to express A phrase representing the idea that someone cannot just keep doing something or waste time being consumed by some emotion.. A phrase representing the idea that someone cannot just keep doing something or waste time being consumed by some emotion.']::text[],ARRAY['The core sense is A phrase representing the idea that someone cannot just keep doing something or waste time being consumed by some emotion.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"過去の業績に安住してばかりはいられない。","japanese_furigana":"過去の業績に安住してばかりはいられない。","english":"We just cannot be content with our past performance."},{"japanese":"確かにこれは深刻な事態だが、議論ばかりしてはいられない。","japanese_furigana":"確かにこれは深刻な事態だが、議論ばかりしてはいられない。","english":"Indeed, this is a serious situation, but we cannot just keep discussing it."}]'::jsonb),
    ('66d29a5c-ec8e-42ed-b5a6-d3c057a37191'::uuid,ARRAY['V1 ても V2 ても Where V1=V2']::text[],ARRAY['Use this construction to express A structure meaning “even if someone does something repeatedly”.. A structure meaning “even if someone does something repeatedly”.']::text[],ARRAY['【Related Expression: いくら~ても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"考えても考えても思い出せない。","japanese_furigana":"考えても考えても思い出せない。","english":"No matter how much/hard I try (literally: think), I cannot remember it."},{"japanese":"働いても働いてもお金が貯まらない。","japanese_furigana":"働いても働いてもお金が貯まらない。","english":"No matter how much/hard I work, I cannot save money."}]'::jsonb),
    ('39f22b9c-73d9-4c3e-a1b9-f4c3d1c734be'::uuid,ARRAY['(i) Noun { でも / じゃ } あるまいし']::text[],ARRAY['Use this construction to express A phrase expressing the speaker’s belief that someone’s action is based on mistaken identity of himself/herself and also expressing the speaker’s critical comments about someone’s behaviour.. A phrase expressing the speaker’s belief that someone’s action is based on mistaken identity of himself/herself and also expressing the speaker’s critical comments about someone’s behaviour.']::text[],ARRAY['The core sense is A phrase expressing the speaker’s belief that someone’s action is based on mistaken identity of himself/herself and also expressing the speaker’s critical comments about someone’s behaviour.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"幼稚園児｛でも/じゃ｝あるまいし一人で学校に行きなさい。","japanese_furigana":"幼稚園児｛でも/じゃ｝あるまいし一人で学校に行きなさい。","english":"You are not a kindergarten pupil. Go to school by yourself."},{"japanese":"フランスに行けるわけ｛でも/じゃ｝あるまいし、どうしてそんなにフランス語を勉強しているの。","japanese_furigana":"フランスに行けるわけ｛でも/じゃ｝あるまいし、どうしてそんなにフランス語を勉強しているの。","english":"There''s no way you can get to France. How come you''re studying French so hard?"}]'::jsonb),
    ('4cf653c2-cfb1-4a07-89aa-d1e1f34661f3'::uuid,ARRAY['Noun (particle) でも, (Noun (particle) でも,) でも 、Wh-word (particle) でも']::text[],ARRAY['Use this construction to express A structure indicating that what is expressed in the main/subordinate clause is applicable to anyone, anything, any place or any time.. A structure indicating that what is expressed in the main/subordinate clause is applicable to anyone, anything, any place or any time.']::text[],ARRAY['The core sense is A structure indicating that what is expressed in the main/subordinate clause is applicable to anyone, anything, any place or any time.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"そんなことは子供でも誰でも知っているよ。","japanese_furigana":"そんなことは子供でも誰でも知っているよ。","english":"That sort of thing is known even to a child or to anybody."},{"japanese":"私って漫画でも何でも読み出すと止まらないタイプなの。","japanese_furigana":"私って漫画でも何でも読み出すと止まらないタイプなの。","english":"I''m the type of person who cannot stop reading manga or whatever once I start."}]'::jsonb),
    ('a225fc5e-889f-434e-939a-67ada1738569'::uuid,ARRAY['Vて やる']::text[],ARRAY['Use this construction to express An auxiliary verb which expresses the idea that someone does something undesirable to someone else when he/she knows his/her action will cause hardship or trouble.. An auxiliary verb which expresses the idea that someone does something undesirable to someone else when he/she knows his/her action will cause hardship or trouble.']::text[],ARRAY['【Related Expression: くれる; もらう】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は正をからかってやった。","japanese_furigana":"私は正をからかってやった。","english":"I teased Tadashi."},{"japanese":"ルームメートが部屋を全然掃除しないので、文句を言ってやった。","japanese_furigana":"ルームメートが部屋を全然掃除しないので、文句を言ってやった。","english":"Because my roommate never cleans our room, I complained (to her about it)."}]'::jsonb),
    ('a6cb88eb-b316-4316-a624-555db06ad46e'::uuid,ARRAY['(i) Verb て仕方がない']::text[],ARRAY['Use this construction to express A phrase that represents emotions the speaker/writer cannot control or sensations/situations he/she cannot bear.. A phrase that represents emotions the speaker/writer cannot control or sensations/situations he/she cannot bear.']::text[],ARRAY['【Related Expression: てならない; て堪らない; (とい)ったらない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"会社の理不尽なリストラに腹が立って仕方がない。","japanese_furigana":"会社の理不尽なリストラに腹が立って仕方がない。","english":"I''m so mad at the company''s unreasonable restructuring (i.e., laying off workers) (and cannot control my anger)."},{"japanese":"久しぶりに妻や子供たちに会えるので嬉しくて仕方がない。","japanese_furigana":"久しぶりに妻や子供たちに会えるので嬉しくて仕方がない。","english":"Because I get to see my wife and children for the ﬁrst time in a long while, I am so happy (and can hardly control my emotion)."}]'::jsonb),
    ('4c94a2ea-8303-42ff-b38e-81607fcfee69'::uuid,ARRAY['Vて 初めて']::text[],ARRAY['Use this construction to express A phrase which expresses the idea that someone does something or something happens only after something else happens or something else is done.. A phrase which expresses the idea that someone does something or something happens only after something else happens or something else is done.']::text[],ARRAY['The core sense is A phrase which expresses the idea that someone does something or something happens only after something else happens or something else is done.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"アメリカへ来て初めて竜巻を見た。","japanese_furigana":"アメリカへ来て初めて竜巻を見た。","english":"It was not until I came to America that I saw a tornado."},{"japanese":"日本で生活して初めて日本人のものの考え方が分かってきた。","japanese_furigana":"日本で生活して初めて日本人のものの考え方が分かってきた。","english":"It was not until I lived in Japan that I started to understand how Japanese people think."}]'::jsonb),
    ('694af1db-40e5-40fa-83d6-f7f480de1b37'::uuid,ARRAY['Canonical pattern: 〜と（並列）']::text[],ARRAY['Use this construction to express A particle which lists things exhaustively.. A particle which lists things exhaustively.']::text[],ARRAY['【Related Expression: に (and); と2; や】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"マイクとディック（と）は学生だ・です。","japanese_furigana":"マイクとディック（と）は学生だ・です。","english":"Mike and Dick are students."},{"japanese":"私は英語と日本語を話す。","japanese_furigana":"私は英語と日本語を話す。","english":"I speak English and Japanese."}]'::jsonb),
    ('cb97461f-85c5-408c-b1b9-4795e213f07b'::uuid,ARRAY['Canonical pattern: 〜と（相手）']::text[],ARRAY['Use this construction to express A particle marking the noun phrase which maintains a reciprocal relationship with the subject of a clause.. A particle marking the noun phrase which maintains a reciprocal relationship with the subject of a clause.']::text[],ARRAY['【Related Expression: に4; と1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はアンディーと一緒にパーティーに行った・行きました。","japanese_furigana":"私はアンディーと一緒にパーティーに行った・行きました。","english":"I went to a party (together) with Andy."},{"japanese":"トムはジョンとよくテニスをする。","japanese_furigana":"トムはジョンとよくテニスをする。","english":"Tom often plays tennis with John."}]'::jsonb),
    ('4df7519d-e2f8-47a7-82fe-9bcfe7801787'::uuid,ARRAY['(i) NP とあって']::text[],ARRAY['Use this construction to express A phrase that introduces a reason when the speaker/writer considers it natural that someone does something or is in some state, or that something takes place for that reason.. A phrase that introduces a reason when the speaker/writer considers it natural that someone does something or is in some state, or that something takes place for that reason.']::text[],ARRAY['【Related Expression: ので; から】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ボーナス後の連休とあって、観光地はどこも人でいっぱいだ。","japanese_furigana":"ボーナス後の連休とあって、観光地はどこも人でいっぱいだ。","english":"Because this is the series of holidays after the bonus season, (not surprisingly) all the tourist spots are crowded."},{"japanese":"夏休みが始まったとあって、子供たちはみんな嬉しそうだ。","japanese_furigana":"夏休みが始まったとあって、子供たちはみんな嬉しそうだ。","english":"Summer vacation has begun, so the children all look happy."}]'::jsonb),
    ('c740cefa-af3d-422e-ba0c-26e0f1a6d0b0'::uuid,ARRAY['Noun 1 といい Noun 2 といい']::text[],ARRAY['Use this construction to express A structure that introduces multiple perspectives when describing a person or a thing.. A structure that introduces multiple perspectives when describing a person or a thing.']::text[],ARRAY['【Related Expression: も~も】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このコーヒーは味といい香りといい、申し分ありません。","japanese_furigana":"このコーヒーは味といい香りといい、申し分ありません。","english":"This coffee is perfect in terms of both ﬂavour and aroma."},{"japanese":"内容といい話し方といい、見事なスピーチでした。","japanese_furigana":"内容といい話し方といい、見事なスピーチでした。","english":"It was a splendid speech in terms of content as well as delivery."}]'::jsonb),
    ('e2ea22d7-f58c-407d-87f5-fada53acb3eb'::uuid,ARRAY['Canonical pattern: 〜という']::text[],ARRAY['Use this construction to express A phrase marking information which identifies or explains the noun following the phrase.. A phrase marking information which identifies or explains the noun following the phrase.']::text[],ARRAY['The core sense is A phrase marking information which identifies or explains the noun following the phrase.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"「雪国」という小説を読んだ・読みました。","japanese_furigana":"「雪国」という小説を読んだ・読みました。","english":"I read a novel called Snow Country."},{"japanese":"山田さんが入院したという知らせを聞いた・聞きました。","japanese_furigana":"山田さんが入院したという知らせを聞いた・聞きました。","english":"I heard the news that Mr. Yamada has been hospitalised."}]'::jsonb),
    ('a7433de0-11cf-4ca1-8572-9f24c7154a2d'::uuid,ARRAY['Sinformal ということは']::text[],ARRAY['Use this construction to express A phrase which changes a sentence into a topic noun clause.. A phrase which changes a sentence into a topic noun clause.']::text[],ARRAY['【Related Expression: こと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼がこの集まりに来ないということは考えられない。","japanese_furigana":"彼がこの集まりに来ないということは考えられない。","english":"It is unthinkable that he won''t come to this meeting."},{"japanese":"手紙が戻って来たということは彼女はもうこの住所にはいないということだ。","japanese_furigana":"手紙が戻って来たということは彼女はもうこの住所にはいないということだ。","english":"The fact that the letter came back means that she no longer lives at this address."}]'::jsonb),
    ('41388aa9-f254-4682-8922-dc8542d3d8e7'::uuid,ARRAY['(i) Noun/Adjective な stem というのは']::text[],ARRAY['Use this construction to express A structure which is used in interpreting, explaining, or defining a word, a phrase, or a sentence.. A structure which is used in interpreting, explaining, or defining a word, a phrase, or a sentence.']::text[],ARRAY['【Related Expression: と言うことは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"パソコンというのはパーソナル・コンピュータのことだ。","japanese_furigana":"パソコンというのはパーソナル・コンピュータのことだ。","english":"Pasokon means personal computer."},{"japanese":"過労死というのは働き過ぎがもとで死ぬ（という）ことだ。","japanese_furigana":"過労死というのは働き過ぎがもとで死ぬ（という）ことだ。","english":"Karoushi means to die from overwork."}]'::jsonb),
    ('60e37d71-51d9-42c4-9576-a1318baf09c5'::uuid,ARRAY['(i) Adjective い informal というより ( は )、(むしろ)Adjective い/な']::text[],ARRAY['Use this construction to express A phrase that is used to indicate more accurate characterisation of someone or something.. A phrase that is used to indicate more accurate characterisation of someone or something.']::text[],ARRAY['The core sense is A phrase that is used to indicate more accurate characterisation of someone or something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"今年の夏は涼しいというよりは寒かった。","japanese_furigana":"今年の夏は涼しいというよりは寒かった。","english":"This summer was cold rather than cool."},{"japanese":"カーラは臆病というより（は）むしろ用心深い。","japanese_furigana":"カーラは臆病というより（は）むしろ用心深い。","english":"Kara is cautious rather than timid."}]'::jsonb),
    ('2fe027ca-d237-461d-b5e6-aab7b200255f'::uuid,ARRAY['(i) Sinformal という風に']::text[],ARRAY['Use this construction to express A phrase which expresses a manner or a way in which someone does something.. A phrase which expresses a manner or a way in which someone does something.']::text[],ARRAY['【Related Expression: と言うように】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼はどうしようもないという風に首を振った。","japanese_furigana":"彼はどうしようもないという風に首を振った。","english":"He shook his head as if to say that there was no way out."},{"japanese":"私は河村さんは来られないという風に聞いている。","japanese_furigana":"私は河村さんは来られないという風に聞いている。","english":"I have been informed that Mr. Kawamura cannot come. (literally: I have been informed in such a way that I understand that Mr. Kawamura cannot come.)"}]'::jsonb),
    ('4d10eb99-ec53-47e2-a33d-33002c4862a2'::uuid,ARRAY['(i) Noun 1 、Noun 2 (、…) といった Noun']::text[],ARRAY['Use this construction to express A compound particle that introduces examples.. A compound particle that introduces examples.']::text[],ARRAY['【Related Expression: と言う; と言うような; などの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ドイツ、フランス、ロシアといった国々が戦争に反対した。","japanese_furigana":"ドイツ、フランス、ロシアといった国々が戦争に反対した。","english":"Countries such as Germany, France and Russia opposed the war."},{"japanese":"このエンジンで一番困るのはパワーが弱い、製造コストが高いといった問題だ。","japanese_furigana":"このエンジンで一番困るのはパワーが弱い、製造コストが高いといった問題だ。","english":"The problems that are giving me the most trouble with this engine are things like weak power and high production costs."}]'::jsonb),
    ('b4344a6f-8fd1-4842-9c3d-43d64c6748d4'::uuid,ARRAY['(i) {V/Adjectiveい}informal といったところだ 。']::text[],ARRAY['Use this construction to express A phrase the speaker/writer uses to explain something in a brief/rough manner.. A phrase the speaker/writer uses to explain something in a brief/rough manner.']::text[],ARRAY['The core sense is A phrase the speaker/writer uses to explain something in a brief/rough manner.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"9月になって猛暑も一段落といったところです。","japanese_furigana":"9月になって猛暑も一段落といったところです。","english":"I''d say the searing heat levelled off in September."},{"japanese":"ここは山というよりは、小高い丘といったところだ。","japanese_furigana":"ここは山というよりは、小高い丘といったところだ。","english":"I''d say that this is more of a (small) hill than a mountain."}]'::jsonb),
    ('ed20a2b3-1b70-43b4-aff1-0a47c015d129'::uuid,ARRAY['(i) どうにも Vpotential negative ない']::text[],ARRAY['Use this construction to express A structure indicating that no matter how hard someone may try, something is impossible.. A structure indicating that no matter how hard someone may try, something is impossible.']::text[],ARRAY['【Related Expression: どうにもこうにも~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私には小説などはどうにも書けない。","japanese_furigana":"私には小説などはどうにも書けない。","english":"I’d never be able to write something like a novel, no matter how hard I try."},{"japanese":"この作文は間違いがひどくてどうにも直しようがない。","japanese_furigana":"この作文は間違いがひどくてどうにも直しようがない。","english":"This composition has such awful mistakes that there is no way to ﬁx it."}]'::jsonb),
    ('becf6c13-e5ca-46ef-b271-04488c10771a'::uuid,ARRAY['(i) {V/Adjectiveい}informal ところから']::text[],ARRAY['Use this construction to express A phrase that introduces the origins of names, theories, ideas and events.. A phrase that introduces the origins of names, theories, ideas and events.']::text[],ARRAY['【Related Expression: ことから; ので; から】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この宝石は猫の目に似ているところから「猫目石」と名づけられている。","japanese_furigana":"この宝石は猫の目に似ているところから「猫目石」と名づけられている。","english":"This gem is called \"cat''s-eye\" because it resembles a cat''s eye."},{"japanese":"私が両者にそのことを十分説明しなかったところから誤解が生じた。","japanese_furigana":"私が両者にそのことを十分説明しなかったところから誤解が生じた。","english":"The misunderstanding was caused by the fact that I didn''t explain it to both of them fully."}]'::jsonb),
    ('e7e434c4-928d-48c7-a79d-d64121c21019'::uuid,ARRAY['(i) Vinformal ところだ']::text[],ARRAY['Use this construction to express Someone/something is in the state where he/it is just about to do something, is doing something, has done something, or has been doing something.. Someone/something is in the state where he/it is just about to do something, is doing something, has done something, or has been doing something.']::text[],ARRAY['【Related Expression: ばかり; 時】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"春江は晩ご飯を食べるところだ・です。","japanese_furigana":"春江は晩ご飯を食べるところだ・です。","english":"Harue is just about to eat her supper."},{"japanese":"春江は晩ご飯を食べているところだ・です。","japanese_furigana":"春江は晩ご飯を食べているところだ・です。","english":"Harue is in the midst of eating her supper."}]'::jsonb),
    ('517a1512-7fa2-458c-9bd3-b7d95b4964ca'::uuid,ARRAY['(i) {V/Adjectiveい}informal nonpast どころではない']::text[],ARRAY['Use this construction to express A phrase indicating that an action/state is simply impossible due to an adverse situation.. A phrase indicating that an action/state is simply impossible due to an adverse situation.']::text[],ARRAY['【Related Expression: どころか; こどろのはなしではない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"自分のことで精一杯で、人のことなど考えるどころではない。","japanese_furigana":"自分のことで精一杯で、人のことなど考えるどころではない。","english":"I''m so busy with my own things that I simply can''t think of other people''s matters (right now)."},{"japanese":"年末なのに多忙で、海外旅行（をする）どころではなかった。","japanese_furigana":"年末なのに多忙で、海外旅行（をする）どころではなかった。","english":"I was so busy toward the end of the year that there was no way I could travel abroad."}]'::jsonb),
    ('09186c04-d80b-4edc-9d7d-9dad00b7a334'::uuid,ARRAY['Noun として']::text[],ARRAY['Use this construction to express A compound particle which indicates the capacity, role or function of someone or something.. A compound particle which indicates the capacity, role or function of someone or something.']::text[],ARRAY['The core sense is A compound particle which indicates the capacity, role or function of someone or something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"田中さんはセールスマンとして採用された・されました。","japanese_furigana":"田中さんはセールスマンとして採用された・されました。","english":"Mr. Tanaka was hired as a salesman."},{"japanese":"私は医者としてあなたに言います。","japanese_furigana":"私は医者としてあなたに言います。","english":"I''ll tell you (this) as a doctor."}]'::jsonb),
    ('20002886-16f1-4905-84e4-f40d5bd70e63'::uuid,ARRAY['Noun としては']::text[],ARRAY['Use this construction to express A compound particle which indicates a standard for comparisons.. A compound particle which indicates a standard for comparisons.']::text[],ARRAY['【Related Expression: にしては】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このステーキは日本のステーキとしては安い・安いです。","japanese_furigana":"このステーキは日本のステーキとしては安い・安いです。","english":"This steak is inexpensive for Japanese steak."},{"japanese":"ジョンソンさんは日本語の一年生としては日本語が上手だ。","japanese_furigana":"ジョンソンさんは日本語の一年生としては日本語が上手だ。","english":"Mr. Johnson is good at Japanese for a first-year student (of Japanese)."}]'::jsonb),
    ('e052ceed-11d7-4d35-95d3-35fed2f13abf'::uuid,ARRAY['(i) Noun 1 は Noun 2 (だ) とする']::text[],ARRAY['Use this construction to express A phrase indicating that someone assumes something.. A phrase indicating that someone assumes something.']::text[],ARRAY['【Related Expression: にする; となると】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"温度は一定（だ）とする。","japanese_furigana":"温度は一定（だ）とする。","english":"We assume that the temperature is constant."},{"japanese":"一日に五百マイル運転できるとすれば・すると、何日で着きますか。","japanese_furigana":"一日に五百マイル運転できるとすれば・すると、何日で着きますか。","english":"Assuming that we can drive 500 miles a day, how many days will it take to get there?"}]'::jsonb),
    ('c92c7d01-6324-4097-80a2-aed9f56b855f'::uuid,ARRAY['Sound Symbolism とする']::text[],ARRAY['Use this construction to express To have a sensory or psychological experience.. To have a sensory or psychological experience.']::text[],ARRAY['The core sense is To have a sensory or psychological experience.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"あの人はちょっとしたことでかっとする。","japanese_furigana":"あの人はちょっとしたことでかっとする。","english":"That person flares up at the slightest provocation."},{"japanese":"あの男の人は目がギョロリとしている。","japanese_furigana":"あの男の人は目がギョロリとしている。","english":"He has goggling eyes."}]'::jsonb),
    ('71e79adf-04da-4ffc-a5b3-8047c3a5ade8'::uuid,ARRAY['(i) どちらかと言うと (Xというよりは)Y。 Where X=Noun{∅/だ/だった}/Adjectiveいinformal/Adjectiveなstem{∅/だ/だった}; Y=Noun{だ/だった}/Adjectiveいinformal/Adjectiveな{だ/だった}']::text[],ARRAY['Use this construction to express A phrase indicating that the speaker/writer chooses one alternative over another in a tentative way.. A phrase indicating that the speaker/writer chooses one alternative over another in a tentative way.']::text[],ARRAY['【Related Expression: どちらかと言えば; むしろ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼はどちらかと言うと教育者というより（は）研究者だ。","japanese_furigana":"彼はどちらかと言うと教育者というより（は）研究者だ。","english":"He is more like a researcher than an educator."},{"japanese":"私はどちらかと言うと外向的というより（は）内向的だ。","japanese_furigana":"私はどちらかと言うと外向的というより（は）内向的だ。","english":"I''m more of an introvert than an extrovert."}]'::jsonb),
    ('28909ff4-ffbe-4365-93b4-4f02d11aaa25'::uuid,ARRAY['(i) とても Vnegative ない']::text[],ARRAY['Use this construction to express A structure that is used to deny emphatically the ability of someone/something or possibility of an event, state or action. A structure that is used to deny emphatically the ability of someone/something or possibility of an event, state or action']::text[],ARRAY['【Related Expression: とうてい~ない; 全く~ない; 決して~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この仕事はとても私にはできない。","japanese_furigana":"この仕事はとても私にはできない。","english":"I cannot possibly do this job."},{"japanese":"吉岡さんはとても私の勝てる相手ではない。","japanese_furigana":"吉岡さんはとても私の勝てる相手ではない。","english":"Mr. Yoshioka is someone I couldn''t possibly beat. (literally: Mr. Yoshioka is not someone I could possibly beat.)"}]'::jsonb),
    ('52b2c658-b753-4bd8-b4bd-ff45f3aa1208'::uuid,ARRAY['(i) Noun 1 とでも言うべき Noun 2']::text[],ARRAY['Use this construction to express A phrase that introduces a noun (or noun phrase) to describe the nature of someone or something.. A phrase that introduces a noun (or noun phrase) to describe the nature of someone or something.']::text[],ARRAY['【Related Expression: と言う; である; のような】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あれは運命とでも言うべき出来事だった。","japanese_furigana":"あれは運命とでも言うべき出来事だった。","english":"That was an incident that could be called fate."},{"japanese":"これはエッセイ的なサイトとでも言うべきでしょう。","japanese_furigana":"これはエッセイ的なサイトとでも言うべきでしょう。","english":"This should probably be described as an essay-like website."}]'::jsonb),
    ('882dd8cf-0f77-4882-b46e-7b79ccf21bbc'::uuid,ARRAY['Noun となる']::text[],ARRAY['Use this construction to express A phrase which expresses the idea that someone or something becomes something.. A phrase which expresses the idea that someone or something becomes something.']::text[],ARRAY['The core sense is A phrase which expresses the idea that someone or something becomes something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"吉田さんが初代の委員長となった。","japanese_furigana":"吉田さんが初代の委員長となった。","english":"Mr. Yoshida has become the first committee chairman."},{"japanese":"その土地は結局国の所有物となった。","japanese_furigana":"その土地は結局国の所有物となった。","english":"That land eventually become state property."}]'::jsonb),
    ('d4f16dce-a99e-4d61-8d0f-b2ef26c8e914'::uuid,ARRAY['(i) Noun となると']::text[],ARRAY['Use this construction to express A phrase which expresses the idea "when it comes to" or "if it is true that".. A phrase which expresses the idea "when it comes to" or "if it is true that".']::text[],ARRAY['【Related Expression: とすると】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は機械のこととなると何も分からない。","japanese_furigana":"私は機械のこととなると何も分からない。","english":"When it comes to mechanical things, I don''t understand anything."},{"japanese":"彼が手伝ってくれないとなると誰かほかの人を頼むしかない。","japanese_furigana":"彼が手伝ってくれないとなると誰かほかの人を頼むしかない。","english":"If it''s true that he is not going to help us, we''ll have no alternative but to ask someone else."}]'::jsonb),
    ('770d320d-8568-47fe-828e-7aab14b72052'::uuid,ARRAY['Sinformal との Noun だ after Adjectiveなstem and Noun is often omitted']::text[],ARRAY['Use this construction to express A phrase that presents the content of the referent of the following noun (e.g., a report, notice, news, view).. A phrase that presents the content of the referent of the following noun (e.g., a report, notice, news, view).']::text[],ARRAY['【Related Expression: という】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"経済情勢は悪化しているとの見方が優勢だ。","japanese_furigana":"経済情勢は悪化しているとの見方が優勢だ。","english":"The view that the economic situation is worsening is dominant."},{"japanese":"邦画の入場者数がハリウッド映画を上回って1位になったのは始めて(だ)とのことだ。","japanese_furigana":"邦画の入場者数がハリウッド映画を上回って1位になったのは始めて(だ)とのことだ。","english":"(It is said that) Apparently this is the first time that the size of the audience for a Japanese movie has exceeded that of a Hollywood movie, making it No. 1."}]'::jsonb),
    ('82a8f0ad-439f-4432-9141-346eff715e5e'::uuid,ARRAY['(i) {V/Adjectiveい}informal とは']::text[],ARRAY['Use this construction to express A compound particle marking an event, action or state that the speaker/writer does not expect and that causes him/her to feel some emotion. A compound particle marking an event, action or state that the speaker/writer does not expect and that causes him/her to feel some emotion']::text[],ARRAY['【Related Expression: と言うのは; ことに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼が自分のベンチャー会社を立ち上げるとは思いもしなかった。","japanese_furigana":"彼が自分のベンチャー会社を立ち上げるとは思いもしなかった。","english":"I never thought that he would launch his own venture business."},{"japanese":"あんないい店がなくなったとは残念だ。","japanese_furigana":"あんないい店がなくなったとは残念だ。","english":"It is too bad that such a nice shop is gone."}]'::jsonb),
    ('19f7d962-88fd-4792-942c-cb15abb9e073'::uuid,ARRAY['(i) Direct Quotation とばかりに']::text[],ARRAY['Use this construction to express A phrase that indicates that someone does something in order to convey something or in such a way that someone is convinced that something is the case.. A phrase that indicates that someone does something in order to convey something or in such a way that someone is convinced that something is the case.']::text[],ARRAY['【Related Expression: といわんばかりに; と言うよう/風に; と】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"悟は「黙ってついてこい」とばかりに先に立って歩き出した。","japanese_furigana":"悟は「黙ってついてこい」とばかりに先に立って歩き出した。","english":"Satoru started off (literally: began to walk ahead) as if to say: \"Don''t say anything and follow me.\""},{"japanese":"課長は余計な質問はするなとばかりに私をにらみつけた。","japanese_furigana":"課長は余計な質問はするなとばかりに私をにらみつけた。","english":"My section chief glared at me as if to tell me not to ask any unnecessary questions."}]'::jsonb),
    ('aada4f12-41e3-4679-9fd3-e9c697667592'::uuid,ARRAY['(i) Sinformal とは言え だ after Adjectiveなstem and Noun is omitted']::text[],ARRAY['Use this construction to express A conjunctive phrase meaning “although it is said that”. A conjunctive phrase meaning “although it is said that”']::text[],ARRAY['【Related Expression: と(は)いっても; とは言うものの】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"夏とは言え、ここはまだちょっと肌寒いくらいの涼しさだ。","japanese_furigana":"夏とは言え、ここはまだちょっと肌寒いくらいの涼しさだ。","english":"Although it is summer, it is still cool here—almost to the extent that it can be called a little chilly."},{"japanese":"時間がなかったとは言え、ジェーンにこれくらいのレポートが書けないはずはない。","japanese_furigana":"時間がなかったとは言え、ジェーンにこれくらいのレポートが書けないはずはない。","english":"(i) Even admitting that Jane didn''t have much time, I don''t believe that she couldn''t write a (simple) report like this. (ii) Although Jane says that she didn''t have much time (or you say that Jane didn''t have much time), I don''t believe that she couldn''t write a (simple) report like this."}]'::jsonb),
    ('29741899-4e9a-483b-9184-7ddfc4a331ae'::uuid,ARRAY['Sinformal とは限らない']::text[],ARRAY['Use this construction to express A phrase which expresses the idea "not necessarily".. A phrase which expresses the idea "not necessarily".']::text[],ARRAY['The core sense is A phrase which expresses the idea "not necessarily".; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"体の弱い人が早く死ぬとは限らない。","japanese_furigana":"体の弱い人が早く死ぬとは限らない。","english":"Frail people do not necessarily die young."},{"japanese":"高い物がいつも・必ずしも安い物よりいいとは限らない。","japanese_furigana":"高い物がいつも・必ずしも安い物よりいいとは限らない。","english":"Expensive things are not always / necessarily better than inexpensive ones."}]'::jsonb),
    ('fa7c0152-e69a-4657-8490-f38b796d8c29'::uuid,ARRAY['ともすると Verb']::text[],ARRAY['Use this construction to express A phrase that expresses the idea that something is likely to take place.. A phrase that expresses the idea that something is likely to take place.']::text[],ARRAY['【Related Expression: ともすれば; ややもすると; ややもすれば; どうかすると】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"切れ味のよい議論はともすると言葉の暴力となる。","japanese_furigana":"切れ味のよい議論はともすると言葉の暴力となる。","english":"A sharp debate is apt to lead to a violent argument."},{"japanese":"親は自分の子供にはともすると点数が甘くなりがちだ。","japanese_furigana":"親は自分の子供にはともすると点数が甘くなりがちだ。","english":"Parents tend to be more permissive (literally: lenient in grading) when it comes to their own children."}]'::jsonb),
    ('0674ce2d-903d-4fe3-9d85-445b6c62f5ca'::uuid,ARRAY['(i) V1informal nonpast ともなく V2 Where V1=V2']::text[],ARRAY['Use this construction to express A phrase indicating that the subject does something without paying much attention, or that when, where, to whom, etc., something took place is unclear.. A phrase indicating that the subject does something without paying much attention, or that when, where, to whom, etc., something took place is unclear.']::text[],ARRAY['【Related Expression: ともなしに; となく】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"散歩をしているうちに、来るともなく駅まで来てしまった。","japanese_furigana":"散歩をしているうちに、来るともなく駅まで来てしまった。","english":"While I was taking a walk, I came as far as the station without intending to."},{"japanese":"我が家ではいつからともなく正月にスキーに行く習慣が始まった。","japanese_furigana":"我が家ではいつからともなく正月にスキーに行く習慣が始まった。","english":"We do not know when, but my family started a tradition of going skiing on New Year''s Day."}]'::jsonb),
    ('4962c626-2b14-4363-a09f-9e24700bb6e8'::uuid,ARRAY['(i) どんなに ～ ( こと ) か']::text[],ARRAY['Use this construction to express A structure that indicates an exclamation about the degree to which an action or state takes/took place.. A structure that indicates an exclamation about the degree to which an action or state takes/took place.']::text[],ARRAY['【Related Expression: どれほど~(こと)は; いかない~(こと)か】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"兄は病気が治ってどんなに嬉しかったことか。","japanese_furigana":"兄は病気が治ってどんなに嬉しかったことか。","english":"How glad my elder brother was when he recovered from his illness!"},{"japanese":"父は母をどんなに愛していたことか。","japanese_furigana":"父は母をどんなに愛していたことか。","english":"How dearly my father loved my mother!"}]'::jsonb),
    ('1aa1f1e8-eed7-4143-b392-78b9b2ff0bc2'::uuid,ARRAY['(i) Noun と共に']::text[],ARRAY['Use this construction to express A phrase which is used to express the idea that A and B share a common property or do the same thing together, that two things take place at the same time, or that someone or something possesses two properties.. A phrase which is used to express the idea that A and B share a common property or do the same thing together, that two things take place at the same time, or that someone or something possesses two properties.']::text[],ARRAY['【Related Expression: に従って; にともなって; につれて; と同時に; と一緒に; と並んで; と同じく】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"スタインベックはへミングウィイと共にアメリカの代表的作家の一人だ。","japanese_furigana":"スタインベックはへミングウィイと共にアメリカの代表的作家の一人だ。","english":"Steinbeck, as well as Hemingway, is a writer representative of American writers."},{"japanese":"私は職場の同僚達と共にそのデモに参加した。","japanese_furigana":"私は職場の同僚達と共にそのデモに参加した。","english":"I took part in the demonstration with my office colleagues."}]'::jsonb),
    ('2854b5b7-c89d-480e-867c-97b13697077e'::uuid,ARRAY['(i) Noun と同時に']::text[],ARRAY['Use this construction to express A phrase which is used to express the idea that someone does something or something takes place at the same time as another action or event, or that someone or something is in two states simultaneously.. A phrase which is used to express the idea that someone does something or something takes place at the same time as another action or event, or that someone or something is in two states simultaneously.']::text[],ARRAY['【Related Expression: と共に; 途端(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼は大学卒業と同時に銀行に就職した。","japanese_furigana":"彼は大学卒業と同時に銀行に就職した。","english":"He got a job at a bank at the time of (literally: at the same time as) his graduation from college."},{"japanese":"部屋に入ると同時に電話が鳴った。","japanese_furigana":"部屋に入ると同時に電話が鳴った。","english":"The telephone rang (literally: at the same time) as I entered the room."}]'::jsonb),
    ('03fcfee0-d0ca-4881-a886-c0ab9334b27c'::uuid,ARRAY['Canonical pattern: 〜と言うか']::text[],ARRAY['Use this construction to express A phrase used to restate what was just said in order to be more accurate or appropriate.. A phrase used to restate what was just said in order to be more accurate or appropriate.']::text[],ARRAY['【Related Expression: と言うより】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"自分の勘違いと言うか、不注意でした。","japanese_furigana":"自分の勘違いと言うか、不注意でした。","english":"It was my misunderstanding . . . or carelessness, rather."},{"japanese":"彼のことは諦めたと言うか、もうどうでもよくなった。","japanese_furigana":"彼のことは諦めたと言うか、もうどうでもよくなった。","english":"I''m through with him. Or rather, I don''t care anymore."}]'::jsonb),
    ('058f6198-7505-4faa-985f-06cb26c21663'::uuid,ARRAY['(i) Noun と言うと']::text[],ARRAY['Use this construction to express A phrase which is used when something which someone has mentioned causes an involuntary response.. A phrase which is used when something which someone has mentioned causes an involuntary response.']::text[],ARRAY['【Related Expression: と言えば】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"サンフランシスコと言うと、あのケーブルカーを思い出す。","japanese_furigana":"サンフランシスコと言うと、あのケーブルカーを思い出す。","english":"When you mention San Francisco, I remember those cable cars."},{"japanese":"日本語を話すと言うと聞こえはいいんですが、実は簡単な挨拶が出来るだけなんです。","japanese_furigana":"日本語を話すと言うと聞こえはいいんですが、実は簡単な挨拶が出来るだけなんです。","english":"It sounds impressive when I say that I can speak Japanese, but the fact is that all I can do is exchange simple greetings."}]'::jsonb),
    ('60116409-6081-4cdf-ac94-b5f8327b407f'::uuid,ARRAY['(i) Sentence1。 と言うのは 、Sentence2。']::text[],ARRAY['Use this construction to express A phrase that introduces the reason for what has just been said.. A phrase that introduces the reason for what has just been said.']::text[],ARRAY['【Related Expression: なぜかと言うと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"来月の旅行は取りやめます。と言うのは、同じ頃に大事なお客が来ることになったんです。","japanese_furigana":"来月の旅行は取りやめます。と言うのは、同じ頃に大事なお客が来ることになったんです。","english":"We are cancelling next month''s trip. I''m saying this because it turns out that we''re going to have an important guest around the same time."},{"japanese":"今まで読めていた画像ファイルがほとんど読めなくなってしまいました。ほとんどと言うのは、少しですが読めるファイルもあるのです。","japanese_furigana":"今まで読めていた画像ファイルがほとんど読めなくなってしまいました。ほとんどと言うのは、少しですが読めるファイルもあるのです。","english":"Almost all the image ﬁles that I have been able to read until now have become unreadable. I say \"almost\" because, even though there are only a few, there are ﬁles that are still readable."}]'::jsonb),
    ('1543eb34-6d91-4410-b580-362314bdfadf'::uuid,ARRAY['(i) Noun と言っても']::text[],ARRAY['Use this construction to express A phrase which is used to clarify a statement in the preceding discourse which might be misleading.. A phrase which is used to clarify a statement in the preceding discourse which might be misleading.']::text[],ARRAY['The core sense is A phrase which is used to clarify a statement in the preceding discourse which might be misleading.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私には子供がいます。子供と言ってももう大学生ですが。","japanese_furigana":"私には子供がいます。子供と言ってももう大学生ですが。","english":"I have a child. Well, although I said, \"child,\" he is already a college student (literally: he is already a college student, though)."},{"japanese":"Ａ：毎日お忙しいんでしょうね。Ｂ：いえ、忙しいと言っても週末は休んでいますから。","japanese_furigana":"Ａ：毎日お忙しいんでしょうね。Ｂ：いえ、忙しいと言っても週末は休んでいますから。","english":"A: You are busy every day, aren''t you? B: No, although people may say that I''m busy, I do not work on weekends, so . . ."}]'::jsonb),
    ('a4dbace0-6d52-4f39-be11-4b94196ded9f'::uuid,ARRAY['Vnegative ないことには ～']::text[],ARRAY['Use this construction to express A phrase that means “if something has not taken place, something else won’t/can’t take place”.. A phrase that means “if something has not taken place, something else won’t/can’t take place”.']::text[],ARRAY['【Related Expression: なくては; なければ; なかったら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この仕事が終わらないことには、家族と旅行に行くこともできない。","japanese_furigana":"この仕事が終わらないことには、家族と旅行に行くこともできない。","english":"If I don''t ﬁnish this work, I can''t go on a trip with my family."},{"japanese":"追加予算が下りないことには、このプロジェクトの遂行は無理だ。","japanese_furigana":"追加予算が下りないことには、このプロジェクトの遂行は無理だ。","english":"Without (money from) an additional budget, it will be impossible to accomplish this project."}]'::jsonb),
    ('cd5ce066-7515-4dbb-bbb0-f4612b4b7395'::uuid,ARRAY['(i) Number1(+Counter) ないし ( は )Number2(+Counter)']::text[],ARRAY['Use this construction to express A particle that presents two possible choices or the minimum and maximum possible numbers/lengths/weights/etc. of something; or a conjunction that links two possible actions or events.. A particle that presents two possible choices or the minimum and maximum possible numbers/lengths/weights/etc. of something; or a conjunction that links two possible actions or events.']::text[],ARRAY['【Related Expression: から; か; または; もしくは; さもなくば; あるいは】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このクラスの学生のほとんどは3年ないし（は）4年の日本語学習歴を持っている。","japanese_furigana":"このクラスの学生のほとんどは3年ないし（は）4年の日本語学習歴を持っている。","english":"Most students in this class have three to four years of experience studying Japanese."},{"japanese":"この論文集の論文はすべて日本語（か）ないしは英語で書かれている。","japanese_furigana":"この論文集の論文はすべて日本語（か）ないしは英語で書かれている。","english":"The papers in this collection are written in Japanese or English."}]'::jsonb),
    ('a7d4b6aa-fef0-4209-8339-faf0e74ca3fc'::uuid,ARRAY['Vnegative ないでもない']::text[],ARRAY['Use this construction to express A phrase that indicates the speaker/writer hesitantly feels or expresses that something is the case.. A phrase that indicates the speaker/writer hesitantly feels or expresses that something is the case.']::text[],ARRAY['【Related Expression: ないこともない; なくもない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今が私の人生で一番幸せな時期だという気がしないでもない。","japanese_furigana":"今が私の人生で一番幸せな時期だという気がしないでもない。","english":"I seem to feel that right now is the happiest time of my life."},{"japanese":"あの時大学を辞めたことを、今では少し早まったなと思わないでもない。","japanese_furigana":"あの時大学を辞めたことを、今では少し早まったなと思わないでもない。","english":"Now I rather feel that leaving the university at that time was a bit too hasty."}]'::jsonb),
    ('668deea1-eff5-4883-9cf6-adeb6297a2dc'::uuid,ARRAY['(i) {Vます/Vてい} ながら ( も )']::text[],ARRAY['Use this construction to express A disjunctive conjunction used normally in written Japanese with the meaning of ''although''.. A disjunctive conjunction used normally in written Japanese with the meaning of ''although''.']::text[],ARRAY['【Related Expression: が; けれど(も); のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この部屋は狭いながら（も）居心地がよい。","japanese_furigana":"この部屋は狭いながら（も）居心地がよい。","english":"Although his room is small, it is comfortable."},{"japanese":"山口はそのことを知りながら（も）黙っていた。","japanese_furigana":"山口はそのことを知りながら（も）黙っていた。","english":"Yamaguchi kept silent, although he knew about the matter."}]'::jsonb),
    ('dfd8301d-cc86-410f-8fb7-eb160d66d312'::uuid,ARRAY['Noun なくして ( は )']::text[],ARRAY['Use this construction to express A compound particle meaning “without something”.. A compound particle meaning “without something”.']::text[],ARRAY['【Related Expression: なしに(は); なしで(は)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"努力なくして（は）この事業はできない。","japanese_furigana":"努力なくして（は）この事業はできない。","english":"Without effort we won''t be able to ﬁnish this undertaking."},{"japanese":"山川教授なくしては今の私は存在しなかったであろう。","japanese_furigana":"山川教授なくしては今の私は存在しなかったであろう。","english":"Without Professor Yamakawa, I wouldn''t be what I am now."}]'::jsonb),
    ('4dae5301-7a7d-4d02-8c32-48e913c76e54'::uuid,ARRAY['Sentence。 なぜなら ( ば )～ からだ 。']::text[],ARRAY['Use this construction to express A structure used to introduce a reason for the statement in the preceding sentence.. A structure used to introduce a reason for the statement in the preceding sentence.']::text[],ARRAY['【Related Expression: から; ので; なぜかと言うと~からだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼はみんなに好かれている。なぜなら（ば）、誰にでも親切だからだ。","japanese_furigana":"彼はみんなに好かれている。なぜなら（ば）、誰にでも親切だからだ。","english":"Everybody likes him. The reason is that he is kind to everybody."},{"japanese":"私は自分が好きです。なぜならば、今を自由に生きているからです。","japanese_furigana":"私は自分が好きです。なぜならば、今を自由に生きているからです。","english":"I like myself. The reason is that I am living freely in the moment."}]'::jsonb),
    ('a49cb6a1-953c-435c-8753-9ac8c02496e1'::uuid,ARRAY['(i) {V/Adjective い}informal などと']::text[],ARRAY['Use this construction to express A compound particle that indicates an approximate quote of words or ideas.. A compound particle that indicates an approximate quote of words or ideas.']::text[],ARRAY['The core sense is A compound particle that indicates an approximate quote of words or ideas.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"日本の文化はユニークだなどと言う人がいるが、私はそうは思わない。","japanese_furigana":"日本の文化はユニークだなどと言う人がいるが、私はそうは思わない。","english":"There are people who say things like Japanese culture is unique, but I don''t think so."},{"japanese":"お金がないから、日本へ行くなどということは夢です。","japanese_furigana":"お金がないから、日本へ行くなどということは夢です。","english":"I don''t have money, so ideas like going to Japan are just dreams."}]'::jsonb),
    ('0caba1cb-ea42-4468-9ffe-8f4b87e48d39'::uuid,ARRAY['(i) NP1 ならではの NP2']::text[],ARRAY['Use this construction to express A phrase indicating something is “impossible if it’s not X”.. A phrase indicating something is “impossible if it’s not X”.']::text[],ARRAY['【Related Expression: でなければ; でなくては; でないと; でなかったら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"丸山博士の講演は、一流の科学者ならではの示唆に富む内容だった。","japanese_furigana":"丸山博士の講演は、一流の科学者ならではの示唆に富む内容だった。","english":"Dr. Maruyama''s lecture was rich with suggestion, the likes of which could only be heard from a ﬁrst-class scientist (like himself)."},{"japanese":"四季を通じて美しい景色が楽しめるのはこの地ならではだ。","japanese_furigana":"四季を通じて美しい景色が楽しめるのはこの地ならではだ。","english":"Only here can we enjoy beautiful scenery through all four seasons."}]'::jsonb),
    ('97899e2d-4697-4e5f-a31c-993cd34eda25'::uuid,ARRAY['(i) Adjective (い/な)て ならない']::text[],ARRAY['Use this construction to express A phrase that is used to express insurmountable psychological or physical feelings.. A phrase that is used to express insurmountable psychological or physical feelings.']::text[],ARRAY['【Related Expression: 堪らない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"病気の母のことが心配でならない。","japanese_furigana":"病気の母のことが心配でならない。","english":"I''m very much worried about my sick mother. (Literally: I cannot help worrying about my sick mother)."},{"japanese":"日本の歴史をもっと深く知りたくてならない。","japanese_furigana":"日本の歴史をもっと深く知りたくてならない。","english":"I''m dying to know Japanese history more deeply."}]'::jsonb),
    ('1856c186-87b8-4fdc-b0f0-f90bbb93d39b'::uuid,ARRAY['(i) Noun なり Noun なり {が/を}']::text[],ARRAY['Use this construction to express A phrase to indicate two representative choices/examples.. A phrase to indicate two representative choices/examples.']::text[],ARRAY['【Related Expression: か~か; たり~たり; とか~とか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"文法が分からなかったら、私なり鈴木先生なりに質問しなさい。","japanese_furigana":"文法が分からなかったら、私なり鈴木先生なりに質問しなさい。","english":"If you don''t understand grammar, ask me or Professor Suzuki."},{"japanese":"読めない漢字は辞書を引くなり、日本人に聞くなりしなさい。","japanese_furigana":"読めない漢字は辞書を引くなり、日本人に聞くなりしなさい。","english":"As for kanji you can''t read, find out the reading either by looking it up in a dictionary or by asking a Japanese."}]'::jsonb),
    ('39e4c783-c7c1-4126-999f-25d5ccc2fa09'::uuid,ARRAY['(i) {V/Adjectiveい}informal なんて']::text[],ARRAY['Use this construction to express A colloquial particle used to express a strong feeling such as astonishment, incredulousness, envy, disdain, dislike, happiness, etc.. A colloquial particle used to express a strong feeling such as astonishment, incredulousness, envy, disdain, dislike, happiness, etc.']::text[],ARRAY['【Related Expression: (など)とは; なんか; など】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"小学校からのいじめが中学まで続くなんてひどい。","japanese_furigana":"小学校からのいじめが中学まで続くなんてひどい。","english":"It''s terrible that bullying continues after grade school into junior high."},{"japanese":"最近は電子メールばかり使っていて、手紙なんて滅多に書かない。","japanese_furigana":"最近は電子メールばかり使っていて、手紙なんて滅多に書かない。","english":"Lately I''ve been using only e-mail, and seldom write (a thing like) a letter."}]'::jsonb),
    ('3048843e-02a4-4050-89b9-ae95659dda73'::uuid,ARRAY['V1informal nonpast に V2potential negative Where V1=V2']::text[],ARRAY['Use this construction to express A sentence structure meaning “someone cannot manage to do something”. A sentence structure meaning “someone cannot manage to do something”']::text[],ARRAY['【Related Expression: たくても~ない; たくとも~ない; ようにも~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"後任者が決まらないので、辞めるに辞められない。","japanese_furigana":"後任者が決まらないので、辞めるに辞められない。","english":"Because my successor hasn''t been chosen yet, I haven''t been able to resign (my current position)."},{"japanese":"大事なお客さんからの電話がいつまで待ってもかかってこないので、帰るに帰れない。","japanese_furigana":"大事なお客さんからの電話がいつまで待ってもかかってこないので、帰るに帰れない。","english":"I''ve been waiting a long time for a call from an important customer, but it hasn''t come, so I cannot leave the ofﬁce."}]'::jsonb),
    ('23d20996-476e-407c-8d36-3c34db20aad2'::uuid,ARRAY['Canonical pattern: 〜に（も）なく']::text[],ARRAY['Use this construction to express A phrase that means something unusual happens or someone does something unusual.. A phrase that means something unusual happens or someone does something unusual.']::text[],ARRAY['The core sense is A phrase that means something unusual happens or someone does something unusual.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"彼女は今日はいつに（も）なく陽気だった。","japanese_furigana":"彼女は今日はいつに（も）なく陽気だった。","english":"She was unusually cheerful today."},{"japanese":"宏は「ただいまー」といつになく明るい声で帰ってきた。","japanese_furigana":"宏は「ただいまー」といつになく明るい声で帰ってきた。","english":"Hiroshi came home and said \"I''m home!\" in an unusually cheerful voice."}]'::jsonb),
    ('217a700a-2df1-4add-b0da-b6651c76574b'::uuid,ARRAY['Canonical pattern: 〜に（動作主・起点）']::text[],ARRAY['Use this construction to express A particle that indicates an agent or a source in passive, causative, もらう/てまらう and other receiving constructions.. A particle that indicates an agent or a source in passive, causative, もらう/てまらう and other receiving constructions.']::text[],ARRAY['【Related Expression: から1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"一男は友達に手紙を読まれた・読まれました。","japanese_furigana":"一男は友達に手紙を読まれた・読まれました。","english":"Kazuo''s friend read Kazuo''s letter (and Kazuo was unhappy)."},{"japanese":"秋子は浩にご飯を作らせた・作らせました。","japanese_furigana":"秋子は浩にご飯を作らせた・作らせました。","english":"Akiko made Hiroshi fix a meal."}]'::jsonb),
    ('03b86b4a-064e-427d-9f5b-e90a8cbf0716'::uuid,ARRAY['Canonical pattern: 〜に（存在場所）']::text[],ARRAY['Use this construction to express A particle which indicates the location where someone or something exists.. A particle which indicates the location where someone or something exists.']::text[],ARRAY['【Related Expression: で1; に4】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ヒルさんは今ジョンソンさんのアパートにいる・います。","japanese_furigana":"ヒルさんは今ジョンソンさんのアパートにいる・います。","english":"Mr. Hill is at Mr. Johnson''s apartment now."},{"japanese":"私のクラスには中国人の学生がいる・います。","japanese_furigana":"私のクラスには中国人の学生がいる・います。","english":"There is a Chinese student in my class."}]'::jsonb),
    ('c1201892-ea6e-4c5f-8b37-274c758fff1e'::uuid,ARRAY['Canonical pattern: 〜に（接触面）']::text[],ARRAY['Use this construction to express A particle that indicates the surface of something upon which some action directly takes place.. A particle that indicates the surface of something upon which some action directly takes place.']::text[],ARRAY['【Related Expression: で1; へ (まで, に7); に6】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"子供は紙に絵を書いた・書きました。","japanese_furigana":"子供は紙に絵を書いた・書きました。","english":"A child has drawn a picture on the paper."},{"japanese":"ここにあなたの名前と住所を書いて下さい。","japanese_furigana":"ここにあなたの名前と住所を書いて下さい。","english":"Please write your name and address here."}]'::jsonb),
    ('f63d4185-1e1a-4dc3-bfe7-44579cba4554'::uuid,ARRAY['Canonical pattern: 〜に（時点）']::text[],ARRAY['Use this construction to express A particle that indicates a point of time at which something takes place.. A particle that indicates a point of time at which something takes place.']::text[],ARRAY['【Related Expression: で4】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は毎朝六時半に起きる・起きます。","japanese_furigana":"私は毎朝六時半に起きる・起きます。","english":"I get up at six thirty every morning."},{"japanese":"私は四月一日に生まれました。","japanese_furigana":"私は四月一日に生まれました。","english":"I was born on April 1st."}]'::jsonb),
    ('cf656ae2-ee43-4b97-a147-7354f7b08996'::uuid,ARRAY['Canonical pattern: 〜に（移動先）']::text[],ARRAY['Use this construction to express A particle which indicates a place toward which someone or something moves.. A particle which indicates a place toward which someone or something moves.']::text[],ARRAY['【Related Expression: へ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はきのうサンフランシスコに行った・行きました。","japanese_furigana":"私はきのうサンフランシスコに行った・行きました。","english":"I went to San Francisco yesterday."},{"japanese":"ジムは来年アメリカに帰る。","japanese_furigana":"ジムは来年アメリカに帰る。","english":"Jim is going back to America next year."}]'::jsonb),
    ('bbc8f99e-c0d3-488f-a57a-44729845ff8d'::uuid,ARRAY['Vます に']::text[],ARRAY['Use this construction to express A particle which indicates purpose when someone moves from one place to another.. A particle which indicates purpose when someone moves from one place to another.']::text[],ARRAY['【Related Expression: 為に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はデパートへ贈り物を買いに行った・行きました。","japanese_furigana":"私はデパートへ贈り物を買いに行った・行きました。","english":"I went to a department store to buy a gift"},{"japanese":"学生が質問をしに来た。","japanese_furigana":"学生が質問をしに来た。","english":"A student came to ask questions."}]'::jsonb),
    ('d3d50c32-bc20-4bc7-9450-2d9defefefd5'::uuid,ARRAY['(i) {Verb/Adjective い}informal {でしょう/だろう} に']::text[],ARRAY['Use this construction to express A sentence final particle that expresses the speaker''s feeling of great regret or sympathy.. A sentence final particle that expresses the speaker''s feeling of great regret or sympathy.']::text[],ARRAY['【Related Expression: のに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"昨日来れば夏子に会えたでしょう・だろうに。","japanese_furigana":"昨日来れば夏子に会えたでしょう・だろうに。","english":"If you had come here yesterday, you could have met Natsuko."},{"japanese":"老人が一人で暮らすのはさぞ寂しいでしょう・だろうに。","japanese_furigana":"老人が一人で暮らすのはさぞ寂しいでしょう・だろうに。","english":"It must be lonely for an old man to live alone."}]'::jsonb),
    ('ea672e37-1bd5-4471-9012-b7afa2436526'::uuid,ARRAY['Canonical pattern: 〜に（間接目的語）']::text[],ARRAY['Use this construction to express An indirect object marker.. An indirect object marker.']::text[],ARRAY['The core sense is An indirect object marker.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は母に手紙をよく書く・書きます。","japanese_furigana":"私は母に手紙をよく書く・書きます。","english":"I often write letters to my mother."},{"japanese":"父は僕に時計を呉れた。","japanese_furigana":"父は僕に時計を呉れた。","english":"My father gave me a watch."}]'::jsonb),
    ('30ac4e2b-602c-47cc-9536-9404a237d52b'::uuid,ARRAY['(i) Noun { に / と } もなると']::text[],ARRAY['Use this construction to express A phrase that is used when something or some situation is perceived to be special.. A phrase that is used when something or some situation is perceived to be special.']::text[],ARRAY['【Related Expression: に/ともなれば】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"桜の季節｛に/と｝もなるとこの公園は花見客でにぎわう。","japanese_furigana":"桜の季節｛に/と｝もなるとこの公園は花見客でにぎわう。","english":"In the cherry blossom season (literally: When it becomes the cherry blossom season), this park is packed with cherry blossom viewers."},{"japanese":"外国へ行くともなると、その国の言語や文化を勉強したくなるはずだ。","japanese_furigana":"外国へ行くともなると、その国の言語や文化を勉強したくなるはずだ。","english":"When you go abroad, most likely you will want to study that country''s language and culture."}]'::jsonb),
    ('e4680d20-12af-4ff1-bb8c-60fba47bfc89'::uuid,ARRAY['Noun にいたっては']::text[],ARRAY['Use this construction to express A compound particle that indicates an extreme example.. A compound particle that indicates an extreme example.']::text[],ARRAY['【Related Expression: の場合(は); ときたら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"人間の体は60%が水、魚は75%、くらげにいたっては96%が水だ。","japanese_furigana":"人間の体は60%が水、魚は75%、くらげにいたっては96%が水だ。","english":"Human bodies are 60 percent water, while ﬁsh are 75 percent water. As for jellyﬁsh, the ﬁgure is 96 percent."},{"japanese":"私自身は社会人になってからコンピュータを使い始めたが、新入社員は中学生の頃から、私の子供たちにいたっては、生まれた時から家にコンピュータがある世代だ。","japanese_furigana":"私自身は社会人になってからコンピュータを使い始めたが、新入社員は中学生の頃から、私の子供たちにいたっては、生まれた時から家にコンピュータがある世代だ。","english":"I myself started to use a computer after I graduated and got a job, but the new hires got started on computers when they were still junior high school students. As for my children, they belong to the generation for whom a computer is available at home from the time of their birth."}]'::jsonb),
    ('1511d706-e110-44d2-9b4b-7fd1b4b9547f'::uuid,ARRAY['(i) Noun において']::text[],ARRAY['Use this construction to express A compound particle which indicates the place of an action/event, a state or time.. A compound particle which indicates the place of an action/event, a state or time.']::text[],ARRAY['【Related Expression: で; に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"来年の総会はシカゴのヒルトン・ホテルにおいて行われる。","japanese_furigana":"来年の総会はシカゴのヒルトン・ホテルにおいて行われる。","english":"Next year''s general meeting will be held at the Hilton Hotel in Chicago."},{"japanese":"コンピュータは近い将来においてほとんどの家庭に行き渡るだろう。","japanese_furigana":"コンピュータは近い将来においてほとんどの家庭に行き渡るだろう。","english":"Computers will probably spread to almost every household in the near future."}]'::jsonb),
    ('b584dacc-bf90-4c3b-98cc-b6f009c9f6da'::uuid,ARRAY['(i) Noun に関わらず']::text[],ARRAY['Use this construction to express A compound particle that means “regardless of”. A compound particle that means “regardless of”']::text[],ARRAY['【Related Expression: を問わず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"当社は性別に関わらず同様に昇進できます。","japanese_furigana":"当社は性別に関わらず同様に昇進できます。","english":"At this company, employees are (literally: you can be) promoted equally, regardless of sex."},{"japanese":"出席か欠席かに関わらず同封の葉書でお知らせ下さい。","japanese_furigana":"出席か欠席かに関わらず同封の葉書でお知らせ下さい。","english":"Whether or not you will attend, please inform us (of your intention) using the enclosed postcard."}]'::jsonb),
    ('1d6d5738-6e5f-4bc5-8464-94c283351a36'::uuid,ARRAY['Noun にかけては']::text[],ARRAY['Use this construction to express A compound particle that marks something in which someone excels or has conﬁdence.. A compound particle that marks something in which someone excels or has conﬁdence.']::text[],ARRAY['【Related Expression: については; に関しては; では】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"経済学のノーベル賞を受賞したジョン・ナシュは数学にかけては自分の右に出る者はいないと思っていた。","japanese_furigana":"経済学のノーベル賞を受賞したジョン・ナシュは数学にかけては自分の右に出る者はいないと思っていた。","english":"John Nash, who received a Nobel Prize in economics, thought that when it came to math, nobody was better than he was."},{"japanese":"ジャッキー・チェンは、アクションにかけては右に出る者がいない俳優である。","japanese_furigana":"ジャッキー・チェンは、アクションにかけては右に出る者がいない俳優である。","english":"Jackie Chan is an actor with whom none can compete when it comes to action ﬁlms."}]'::jsonb),
    ('b4faf3c9-2303-48d0-9440-420571a58f88'::uuid,ARRAY['VN に難くない Where VN=Sino-Japanese compound']::text[],ARRAY['Use this construction to express A phrase that indicates that it is not hard to imagine or guess a situation.. A phrase that indicates that it is not hard to imagine or guess a situation.']::text[],ARRAY['The core sense is A phrase that indicates that it is not hard to imagine or guess a situation.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"給料が低いために教師の質が低下した（であろう）ことは想像にかたくない。","japanese_furigana":"給料が低いために教師の質が低下した（であろう）ことは想像にかたくない。","english":"It is not hard to imagine that the quality of teachers fell because of the low salary."},{"japanese":"幼い時に両親を失った彼女の生活が｛いかに/どれほど｝悲惨だったかは推測にかたくない。","japanese_furigana":"幼い時に両親を失った彼女の生活が｛いかに/どれほど｝悲惨だったかは推測にかたくない。","english":"It is easy to guess how miserable her life was after she lost her parents."}]'::jsonb),
    ('41c02383-adbe-4dce-af3f-b09bee8c93e1'::uuid,ARRAY['Noun にしたところで']::text[],ARRAY['Use this construction to express A compound particle that means “even” or “also”.. A compound particle that means “even” or “also”.']::text[],ARRAY['【Related Expression: でも; も; にしてからが】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼は日本語を20年も勉強しているが、その彼にしたところで、まだ分からない文法に時々出くわすそうだ。","japanese_furigana":"彼は日本語を20年も勉強しているが、その彼にしたところで、まだ分からない文法に時々出くわすそうだ。","english":"He has studied Japanese for 20 years, but he told me that even he still encounters grammar he doesn''t understand."},{"japanese":"子供はいつか手の届かないところへ行ってしまうものだ。自分の子だけはそうでないと思うかもしれないが、あなたの子にしたところで同じだ。","japanese_furigana":"子供はいつか手の届かないところへ行ってしまうものだ。自分の子だけはそうでないと思うかもしれないが、あなたの子にしたところで同じだ。","english":"Children go (places) beyond their parents'' reach sooner or later. You may think that your own children will be different, but they, too, will be the same."}]'::jsonb),
    ('ce981808-a62e-4268-9da5-cfa0e6048367'::uuid,ARRAY['(i) Adjectiveなstem にして']::text[],ARRAY['Use this construction to express A conjunction meaning “and” that is used to combine two noun phrases or な-adjectives.. A conjunction meaning “and” that is used to combine two noun phrases or な-adjectives.']::text[],ARRAY['【Related Expression: で】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女は頭脳明晰にして端麗な秘書である。","japanese_furigana":"彼女は頭脳明晰にして端麗な秘書である。","english":"She is a bright and also beautiful secretary."},{"japanese":"彼は偉大な学者にして優れた教育者でもあった。","japanese_furigana":"彼は偉大な学者にして優れた教育者でもあった。","english":"He was both a distinguished scholar and an excellent educator."}]'::jsonb),
    ('09b64db3-83ab-4eb2-95d6-92b5f27fece3'::uuid,ARRAY['(i) Number+Counter にして']::text[],ARRAY['Use this construction to express A compound particle that indicates a period of time/stage (in life) at which some surprising action or state takes place.. A compound particle that indicates a period of time/stage (in life) at which some surprising action or state takes place.']::text[],ARRAY['【Related Expression: で】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"過度の恐怖や心労が一夜にして白髪をつくる。","japanese_furigana":"過度の恐怖や心労が一夜にして白髪をつくる。","english":"Excessive fear and worry will make your hair turn grey overnight."},{"japanese":"彼女は45歳にして初めて子供ができた。","japanese_furigana":"彼女は45歳にして初めて子供ができた。","english":"She had her ﬁrst child at the age of 45."}]'::jsonb),
    ('4a4f12e8-06d4-42cb-ba37-c962ed346a4e'::uuid,ARRAY['Noun にしてからが']::text[],ARRAY['Use this construction to express A compound particle indicating that something unexpected occurs.. A compound particle indicating that something unexpected occurs.']::text[],ARRAY['【Related Expression: でさえ; ですら; からして; にしたところで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ワールドカップの時はサッカーファンでもない私にしてからが興奮状態でした。","japanese_furigana":"ワールドカップの時はサッカーファンでもない私にしてからが興奮状態でした。","english":"I am not a soccer fan, but during the World Cup, even I got excited."},{"japanese":"警察にしてからが、いざ事件が起きないと市民を暴力から守ってくれない。","japanese_furigana":"警察にしてからが、いざ事件が起きないと市民を暴力から守ってくれない。","english":"Even the police don''t protect citizens from violence unless an incident actually occurs."}]'::jsonb),
    ('403f4c4f-84a8-458a-9d74-05a091f180b1'::uuid,ARRAY['(i) Noun ( だった ) にしては']::text[],ARRAY['Use this construction to express A phrase that indicates a generally agreed upon standard (the entire sentence that includes this phrase expresses some deviation from that standard.). A phrase that indicates a generally agreed upon standard (the entire sentence that includes this phrase expresses some deviation from that standard.)']::text[],ARRAY['【Related Expression: としては】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"高山さんは日本人にしては大きい・大きいです。","japanese_furigana":"高山さんは日本人にしては大きい・大きいです。","english":"Mr. Takayama is big for a Japanese person."},{"japanese":"ボブは日本語をよく勉強しているにしては下手だ・下手です。","japanese_furigana":"ボブは日本語をよく勉強しているにしては下手だ・下手です。","english":"Considering that Bob is studying Japanese hard, he is poor at it."}]'::jsonb),
    ('6f4ee887-924f-45b7-9cc8-c4712cd4836f'::uuid,ARRAY['(i) Vinformal に { しろ / せよ }']::text[],ARRAY['Use this construction to express A conjunctive phrase that carries the meaning of concession.. A conjunctive phrase that carries the meaning of concession.']::text[],ARRAY['【Related Expression: にしても; としても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"時間があまりなかったに｛しろ/せよ｝、この仕事はひどすぎる。","japanese_furigana":"時間があまりなかったに｛しろ/せよ｝、この仕事はひどすぎる。","english":"Even though he didn''t have much time, this work is too sloppy."},{"japanese":"誰が書くに｛しろ/せよ｝、絶対間違いがあってはいけない。","japanese_furigana":"誰が書くに｛しろ/せよ｝、絶対間違いがあってはいけない。","english":"No matter who writes it, there can be absolutely no mistakes."}]'::jsonb),
    ('1e3a0cf4-e6dd-4f32-bd19-5960e9b35141'::uuid,ARRAY['Number+Counter につき']::text[],ARRAY['Use this construction to express A compound particle which expresses a rate or ratio.. A compound particle which expresses a rate or ratio.']::text[],ARRAY['【Related Expression: あたり】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この仕事は一時間につき六ドル貰える。","japanese_furigana":"この仕事は一時間につき六ドル貰える。","english":"This job will pay you six dollars an hour. (literally: You can get six dollars an hour doing this job.)"},{"japanese":"一冊につき百五十円の送料が要ります。","japanese_furigana":"一冊につき百五十円の送料が要ります。","english":"A hundred and fifty yen is necessary per copy for postage. (literally: Postage of one hundred and fifty yen is necessary per copy.)"}]'::jsonb),
    ('a2e8fc1f-1c6f-404a-8420-7b37efbb660f'::uuid,ARRAY['(i) Vinformal nonpast につれて']::text[],ARRAY['Use this construction to express A phrase used to indicate that a change occurs in accordance with another simultaneous change.. A phrase used to indicate that a change occurs in accordance with another simultaneous change.']::text[],ARRAY['【Related Expression: に従って/従い; ば~ほど; と共に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語が上達するにつれて日本人の友達が増えた。","japanese_furigana":"日本語が上達するにつれて日本人の友達が増えた。","english":"As my Japanese became more proficient, the number of my Japanese friends increased."},{"japanese":"時代の変化につれて、文化も変わっていく。","japanese_furigana":"時代の変化につれて、文化も変わっていく。","english":"Culture also changes with the change of the times."}]'::jsonb),
    ('c2c9286c-3252-4e7f-a03c-af0bf478927f'::uuid,ARRAY['(i) Noun(だけ) にとどまらず']::text[],ARRAY['Use this construction to express A phrase indicating that something goes beyond a spatial/temporal boundary.. A phrase indicating that something goes beyond a spatial/temporal boundary.']::text[],ARRAY['【Related Expression: だけで(は)なく~(も); のにならず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼の研究範囲は哲学(だけ)にとどまらず、認知心理学の領域にまで広がっている。","japanese_furigana":"彼の研究範囲は哲学(だけ)にとどまらず、認知心理学の領域にまで広がっている。","english":"His area of research is not limited merely to philosophy, but extends to cognitive psychology as well."},{"japanese":"彼女は小説を広く読む(だけ)にとどまらず、自分でもいくつか書いて、すでに雑誌に発表している。","japanese_furigana":"彼女は小説を広く読む(だけ)にとどまらず、自分でもいくつか書いて、すでに雑誌に発表している。","english":"Not only does she avidly read novels, she also has written a couple of novels herself, which have been published in magazines."}]'::jsonb),
    ('0bfd1cf0-c9ed-432c-8600-17a145590052'::uuid,ARRAY['(i) Noun (time) になると']::text[],ARRAY['Use this construction to express A phrase that expresses the time when an uncontrollable state or a habitual action occurs.. A phrase that expresses the time when an uncontrollable state or a habitual action occurs.']::text[],ARRAY['The core sense is A phrase that expresses the time when an uncontrollable state or a habitual action occurs.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"夏になると、摂氏三十度を越す日が多いです。","japanese_furigana":"夏になると、摂氏三十度を越す日が多いです。","english":"In summer (literally: When it becomes summer), there are many days that exceed 30 degrees Celsius."},{"japanese":"父は食べ物のことになると、とてもやかましかった。","japanese_furigana":"父は食べ物のことになると、とてもやかましかった。","english":"When it comes to the matter of food, my father was very particular."}]'::jsonb),
    ('41d6840b-6dc9-4a30-93d8-159b686831f4'::uuid,ARRAY['(i) {Noun/Demonstrative pronoun} にひきかえ']::text[],ARRAY['Use this construction to express A phrase that indicates a sharp contrast.. A phrase that indicates a sharp contrast.']::text[],ARRAY['【Related Expression: に比べると/比べて; 代わりに; に対して】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"几帳面な父にひきかえ、息子はだらしなかった。","japanese_furigana":"几帳面な父にひきかえ、息子はだらしなかった。","english":"The son, in contrast to his meticulous father, was slovenly."},{"japanese":"この大学は教育の質がとてもいいのにひきかえ、学内の設備が劣る。","japanese_furigana":"この大学は教育の質がとてもいいのにひきかえ、学内の設備が劣る。","english":"While the quality of education at this college is excellent, the quality of the campus facilities is inferior."}]'::jsonb),
    ('c72099d8-f838-4572-8f2b-9ff21528e512'::uuid,ARRAY['(i) (Nounは)Noun にはかならない']::text[],ARRAY['Use this construction to express A phrase that is used to indicate that an action/state mentioned in the topic phrase or clause is nothing but something.. A phrase that is used to indicate that an action/state mentioned in the topic phrase or clause is nothing but something.']::text[],ARRAY['【Related Expression: に過ぎない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あの人の言葉は美辞麗句にほかならない。","japanese_furigana":"あの人の言葉は美辞麗句にほかならない。","english":"His words are nothing but flowery words."},{"japanese":"日本語を勉強しているのは将来日本で仕事をしたいからにほかならない。","japanese_furigana":"日本語を勉強しているのは将来日本で仕事をしたいからにほかならない。","english":"The reason that I am studying Japanese is simply because I want to work in Japan in the future."}]'::jsonb),
    ('0243a08b-eeaf-4f6d-879e-767598c5c4a6'::uuid,ARRAY['(i) Noun によって']::text[],ARRAY['Use this construction to express A particle that indicates means, cause, agent of passive sentence, or dependency on a situation.. A particle that indicates means, cause, agent of passive sentence, or dependency on a situation.']::text[],ARRAY['【Related Expression: に; で; の為に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"漢和辞典によって知らない漢字を調べる。","japanese_furigana":"漢和辞典によって知らない漢字を調べる。","english":"We examine unknown kanji with a Chinese character dictionary."},{"japanese":"先生によって、勿論、教え方が違います。","japanese_furigana":"先生によって、勿論、教え方が違います。","english":"Teaching methods are, of course, different, depending on the teacher."}]'::jsonb),
    ('27abb516-ddac-47d6-b6c3-e16ef5974621'::uuid,ARRAY['(i) Noun によらず']::text[],ARRAY['Use this construction to express A compound particle that means “without depending on”.. A compound particle that means “without depending on”.']::text[],ARRAY['【Related Expression: なしで; によって/より; を問わず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"リストラによらず(に)この会社を救う方法はない。","japanese_furigana":"リストラによらず(に)この会社を救う方法はない。","english":"There is no way to save this company without restructuring it."},{"japanese":"この会社では学歴によらず、実力があればどんどん大きい仕事をまかされる。","japanese_furigana":"この会社では学歴によらず、実力があればどんどん大きい仕事をまかされる。","english":"At this company, if you are capable, you will be given big assignments one after another, regardless of your educational qualiﬁcations."}]'::jsonb),
    ('623f2e7c-8385-4a35-bca8-38100e202a1d'::uuid,ARRAY['Noun によると']::text[],ARRAY['Use this construction to express A compound particle that is used to identify the source of information provided in the sentence.. A compound particle that is used to identify the source of information provided in the sentence.']::text[],ARRAY['【Related Expression: によれば】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"その温泉は旅行雑誌によると神経痛にいいそうだ。","japanese_furigana":"その温泉は旅行雑誌によると神経痛にいいそうだ。","english":"One of the travel magazines said that hot springs are good for arthritis."},{"japanese":"日本の法律によるとおおむね12歳未満の者は逮捕の対象にならない。","japanese_furigana":"日本の法律によるとおおむね12歳未満の者は逮捕の対象にならない。","english":"According to Japanese law, generally, youths under 12 are not subject to arrest."}]'::jsonb),
    ('f04df975-22d8-49b8-b910-e7ff7ecbccba'::uuid,ARRAY['(i) Noun にわたって']::text[],ARRAY['Use this construction to express A compound particle indicating that something takes place over a particular span of time or physical space.. A compound particle indicating that something takes place over a particular span of time or physical space.']::text[],ARRAY['【Related Expression: にかけて】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"オリンピックが16日間にわたって開かれた。","japanese_furigana":"オリンピックが16日間にわたって開かれた。","english":"The Olympic Games were held for sixteen days."},{"japanese":"干ばつのため広範囲にわたって作物が被害を受けた。","japanese_furigana":"干ばつのため広範囲にわたって作物が被害を受けた。","english":"Due to the drought, crops were damaged over a wide area."}]'::jsonb),
    ('8651e4fc-6d73-4b90-96aa-ababd63e94d5'::uuid,ARRAY['Noun に代わって']::text[],ARRAY['Use this construction to express A compound particle to express replacement or substitution of a regular person/thing by someone/something.. A compound particle to express replacement or substitution of a regular person/thing by someone/something.']::text[],ARRAY['【Related Expression: 代わりに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"病気の山田先生に代わって、鈴木先生が教えて下さった。","japanese_furigana":"病気の山田先生に代わって、鈴木先生が教えて下さった。","english":"In place of Professor Yamada, who is ill, Professor Suzuki taught us."},{"japanese":"戦後ガラスに代わってプラスチックが出てきた。","japanese_furigana":"戦後ガラスに代わってプラスチックが出てきた。","english":"After the war plastics became available replacing glass."}]'::jsonb),
    ('0f933811-ec02-4eee-a2ab-ddf6536ed068'::uuid,ARRAY['(i) Noun に向けて']::text[],ARRAY['Use this construction to express A compound particle that indicates the destination/direction of movement, the target/direction of an action, or the goal/purpose of an action.. A compound particle that indicates the destination/direction of movement, the target/direction of an action, or the goal/purpose of an action.']::text[],ARRAY['【Related Expression: に向かって; をめざして; を目標; の為に】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"報道班は次の目的地に向けて出発した。","japanese_furigana":"報道班は次の目的地に向けて出発した。","english":"The team of reporters left for the next destination."},{"japanese":"このテレビコマーシャルは20、30代の独身女性に向けて発信されている。","japanese_furigana":"このテレビコマーシャルは20、30代の独身女性に向けて発信されている。","english":"This TV commercial is being marketed to single women in their twenties and thirties."}]'::jsonb),
    ('d1c81e8c-12fa-4855-98a0-4237ee24fff7'::uuid,ARRAY['(i) Noun に { 当たって / 当たり }']::text[],ARRAY['Use this construction to express A compound particle that indicates occasion of doing something or of having done something in formal Japanese.. A compound particle that indicates occasion of doing something or of having done something in formal Japanese.']::text[],ARRAY['【Related Expression: 前に; に際して; 際(に); 時】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"新入社員の入社に{当たって/当たり}社長はホテルでパーティーを開いた。","japanese_furigana":"新入社員の入社に{当たって/当たり}社長はホテルでパーティーを開いた。","english":"On the occasion of new employees'' entering the company, the president threw a party at a hotel."},{"japanese":"和也は大学を卒業するに{当たって/当たり}、指導教官に今後の進路について相談した。","japanese_furigana":"和也は大学を卒業するに{当たって/当たり}、指導教官に今後の進路について相談した。","english":"On the occasion of graduating from college, Kazuya consulted with his academic adviser on his future direction."}]'::jsonb),
    ('58160fe5-3dff-4413-8833-07a0bcdd53b2'::uuid,ARRAY['(i) Noun に応じて']::text[],ARRAY['Use this construction to express A compound particle that means “in response to”.. A compound particle that means “in response to”.']::text[],ARRAY['【Related Expression: によって; 次第で; いかんで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"組合の要求に応じて標準就業時間が短縮されることになった。","japanese_furigana":"組合の要求に応じて標準就業時間が短縮されることになった。","english":"In response to union demands, the standard work day (literally: standard work hours) will be shortened."},{"japanese":"業績に応じて従業員全員にボーナスが支給された。","japanese_furigana":"業績に応じて従業員全員にボーナスが支給された。","english":"Bonuses were distributed to all employees according to their performance (literally: achievements)."}]'::jsonb),
    ('3fee08a5-292b-4703-a952-655b02ee2168'::uuid,ARRAY['(i) {V/Adjectiveい}informal に決まっている']::text[],ARRAY['Use this construction to express A phrase indicating the speaker’s/writer’s strong conviction or motivation.. A phrase indicating the speaker’s/writer’s strong conviction or motivation.']::text[],ARRAY['【Related Expression: に違いない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"性格は、いい方がいいに決まっている。","japanese_furigana":"性格は、いい方がいいに決まっている。","english":"It is a given that a good personality is preferable."},{"japanese":"お客さまだって安く買いたいに決まっているじゃないか。","japanese_furigana":"お客さまだって安く買いたいに決まっているじゃないか。","english":"Of course customers want to buy things cheaply."}]'::jsonb),
    ('2e2e06f4-cb8e-4f60-b563-d16fc75218ca'::uuid,ARRAY['(i) Adjectiveいinformal nonpast に越したことはない']::text[],ARRAY['Use this construction to express A phrase used to indicate that a state or action is more desirable.. A phrase used to indicate that a state or action is more desirable.']::text[],ARRAY['【Related Expression: ば~ほどよい/いい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"仲間は多いに越したことはない。","japanese_furigana":"仲間は多いに越したことはない。","english":"The more buddies you have the better."},{"japanese":"元気（である）に越したことはない。","japanese_furigana":"元気（である）に越したことはない。","english":"The healthier the better."}]'::jsonb),
    ('04468199-b857-4031-a2f9-ac79405b499f'::uuid,ARRAY['Noun に限って']::text[],ARRAY['Use this construction to express A compound particle to show that only X is different from others.. A compound particle to show that only X is different from others.']::text[],ARRAY['The core sense is A compound particle to show that only X is different from others.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"うちの子供に限ってそんなひどいことはしませんよ。","japanese_furigana":"うちの子供に限ってそんなひどいことはしませんよ。","english":"Our child, of all children, would not do such a terrible thing."},{"japanese":"中野先生はたいてい研究室にいらっしゃるのに、今日に限っていらっしゃらなかった。","japanese_furigana":"中野先生はたいてい研究室にいらっしゃるのに、今日に限っていらっしゃらなかった。","english":"Professor Nakano is usually in his office, but today, of all days, he wasn''t there."}]'::jsonb),
    ('a366c42f-3fb6-41e8-9c0c-3aaa8834a2ed'::uuid,ARRAY['Canonical pattern: 〜ね']::text[],ARRAY['Use this construction to express A sentence final particle that indicates the speaker’s request for confirmation or agreement from the hearer about some shared knowledge.. A sentence final particle that indicates the speaker’s request for confirmation or agreement from the hearer about some shared knowledge.']::text[],ARRAY['The core sense is A sentence final particle that indicates the speaker’s request for confirmation or agreement from the hearer about some shared knowledge.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"坂本さんは煙草を吸わない・吸いませんね。","japanese_furigana":"坂本さんは煙草を吸わない・吸いませんね。","english":"Mr. Sakamoto doesn''t smoke, does he? / Mr. Sakamoto, you don''t smoke, do you?"},{"japanese":"A:今日はいい天気ですね。 B:本当にそうですね。","japanese_furigana":"A:今日はいい天気ですね。 B:本当にそうですね。","english":"A: Today is a fine day, isn''t it? B: Isn''t it!"}]'::jsonb),
    ('e9b52877-e1cf-4235-94c7-f2f1e4bd9040'::uuid,ARRAY['Vinformal negative ねばならない']::text[],ARRAY['Use this construction to express A phrase that indicates duty, obligation or necessity.. A phrase that indicates duty, obligation or necessity.']::text[],ARRAY['【Related Expression: なければならない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本を知るためには一度は日本へ行かねばならない。","japanese_furigana":"日本を知るためには一度は日本へ行かねばならない。","english":"In order to know Japan one has to go to Japan at least once."},{"japanese":"日本は市場をもっと広く開放せねばならない。","japanese_furigana":"日本は市場をもっと広く開放せねばならない。","english":"Japan has to open its market wider."}]'::jsonb),
    ('7c26dafa-4d83-4d22-854a-485f81e852b4'::uuid,ARRAY['(i) X(affirmation) の X(negative) のと']::text[],ARRAY['Use this construction to express A structure that states what is said by someone in order to express the speaker’s disagreement or dissatisfaction.. A structure that states what is said by someone in order to express the speaker’s disagreement or dissatisfaction.']::text[],ARRAY['【Related Expression: とか~とか; だの~だのと】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"やったのやらなかったのといつまで言っていても仕方がない。","japanese_furigana":"やったのやらなかったのといつまで言っていても仕方がない。","english":"It is no use talking endlessly about what you did or didn''t do."},{"japanese":"いつまでも好きだの嫌いだのと言っていないで、早く結婚相手を決めなさい。","japanese_furigana":"いつまでも好きだの嫌いだのと言っていないで、早く結婚相手を決めなさい。","english":"You should decide who you want to marry soon without saying all the time that you like (this one) or that you don''t like (that one)."}]'::jsonb)
)
update public.japanese_grammar_guides g
set formation=case when coalesce(array_length(g.formation,1),0)=0 then e.formation_value else g.formation end,
    usage=case when coalesce(array_length(g.usage,1),0)=0 then e.usage_value else g.usage end,
    nuance=case when coalesce(array_length(g.nuance,1),0)=0 then e.nuance_value else g.nuance end,
    reference_examples=case when jsonb_typeof(coalesce(g.reference_examples,'[]'::jsonb))='array' and jsonb_array_length(coalesce(g.reference_examples,'[]'::jsonb))=0 then e.examples_value else g.reference_examples end,
    updated_at=now()
from enrichment e
where g.id=e.grammar_id and g.user_id=(select user_id from private.app_owner);

commit;
